import React, { useEffect, useMemo, useState } from "react";
import {
  Bot,
  CalendarDays,
  MessageSquare,
  Phone,
  TrendingUp,
  Users,
  Mail,
} from "lucide-react";
import DashboardLayout from "./layout/DashboardLayout";

const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL || "http://localhost:8000";

function StatCard({ label, value, icon: Icon, tone = "purple" }) {
  return (
    <div className="rounded-2xl border border-slate-200 bg-white p-7 shadow-sm">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-[13px] font-bold uppercase tracking-wider text-slate-500">
            {label}
          </p>
          <p className="mt-4 text-[30px] font-extrabold leading-none text-slate-950">
            {value}
          </p>
        </div>
        <div
          className={`rounded-xl p-2 ${
            tone === "green"
              ? "bg-emerald-50 text-emerald-600"
              : tone === "blue"
              ? "bg-blue-50 text-blue-600"
              : "bg-purple-50 text-purple-600"
          }`}
        >
          <Icon className="h-5 w-5" />
        </div>
      </div>
    </div>
  );
}

function formatTime(value) {
  if (!value) return "-";
  try {
    return new Date(value).toLocaleString();
  } catch {
    return value;
  }
}

export default function ContactsDashboard() {
  const [contacts, setContacts] = useState([]);
  const [search, setSearch] = useState("");
  const [sourceFilter, setSourceFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchContacts();
  }, []);

  async function fetchContacts() {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("auth_token");

      const response = await fetch(`${API_BASE_URL}/api/contacts`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(result?.detail || "Failed to load contacts");
      }

      setContacts(result?.contacts || []);
    } catch (err) {
      setError(err.message || "Failed to load contacts");
      setContacts([]);
    } finally {
      setLoading(false);
    }
  }

  const filteredContacts = useMemo(() => {
    const q = search.trim().toLowerCase();

    return contacts.filter((item) => {
      const matchesSearch =
        !q ||
        (item.name || "").toLowerCase().includes(q) ||
        (item.email || "").toLowerCase().includes(q) ||
        (item.phone || "").toLowerCase().includes(q) ||
        (item.last_message || "").toLowerCase().includes(q);

      const matchesSource =
        sourceFilter === "all" || (item.source || "") === sourceFilter;

      return matchesSearch && matchesSource;
    });
  }, [contacts, search, sourceFilter]);

  const todayCount = contacts.filter((item) => {
    if (!item.created_at) return false;
    const today = new Date().toDateString();
    return new Date(item.created_at).toDateString() === today;
  }).length;

  const yesterdayCount = contacts.filter((item) => {
    if (!item.created_at) return false;
    const d = new Date();
    d.setDate(d.getDate() - 1);
    return new Date(item.created_at).toDateString() === d.toDateString();
  }).length;

  const last7DaysCount = contacts.filter((item) => {
    if (!item.created_at) return false;
    const created = new Date(item.created_at);
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    return created >= sevenDaysAgo;
  }).length;

  return (
    <DashboardLayout title="Dashboard">
      <div className="mx-auto max-w-[1540px] p-6">
        <div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-center">
          <div>
            <h2 className="text-[30px] font-extrabold tracking-tight text-slate-950">
              Contacts
            </h2>
            <p className="mt-2 text-[17px] text-slate-500">
              Every customer who's spoken to your AI agents — unified across web
              and WhatsApp.
            </p>
          </div>

          <button className="inline-flex items-center gap-3 rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-bold text-slate-700 shadow-sm">
            <CalendarDays className="h-5 w-5 text-slate-400" /> Last 30 Days
          </button>
        </div>

        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
          <StatCard label="New Today" value={todayCount} icon={Bot} />
          <StatCard
            label="New Yesterday"
            value={yesterdayCount}
            icon={CalendarDays}
            tone="blue"
          />
          <StatCard
            label="Last 7 Days"
            value={last7DaysCount}
            icon={TrendingUp}
            tone="green"
          />
          <StatCard label="Total Contacts" value={contacts.length} icon={Users} />
        </div>

        <div className="mt-7 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
          <div className="flex flex-col gap-3 xl:flex-row">
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="h-12 flex-1 rounded-xl border border-slate-300 px-6 text-[18px] outline-none placeholder:text-slate-400 focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
              placeholder="Search by name, email, or phone..."
            />

            <select className="h-12 rounded-xl border border-slate-300 bg-white px-4 text-sm font-semibold text-slate-700 outline-none">
              <option>All AI agents</option>
            </select>

            <select
              value={sourceFilter}
              onChange={(e) => setSourceFilter(e.target.value)}
              className="h-12 rounded-xl border border-slate-300 bg-white px-4 text-sm font-semibold text-slate-700 outline-none"
            >
              <option value="all">All channels</option>
              <option value="public_chat">Web Chat</option>
              <option value="whatsapp">WhatsApp</option>
            </select>
          </div>
        </div>

        <div className="mt-7 rounded-2xl border border-slate-200 bg-white p-7 shadow-sm">
          <div className="mb-6 flex items-center justify-between">
            <h3 className="text-xl font-extrabold text-slate-950">
              Customer Contacts
            </h3>

            <button
              onClick={fetchContacts}
              className="rounded-xl bg-purple-600 px-4 py-2 text-sm font-bold text-white hover:bg-purple-700"
            >
              Refresh
            </button>
          </div>

          {error && (
            <div className="mb-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-semibold text-red-700">
              {error}
            </div>
          )}

          <div className="overflow-x-auto">
            <table className="w-full min-w-[950px] border-collapse">
              <thead>
                <tr className="border-b border-slate-200 text-left">
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-400">
                    Customer
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-400">
                    Contact
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-400">
                    Source
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-400">
                    Last Message
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-400">
                    Status
                  </th>
                  <th className="px-4 py-3 text-xs font-bold uppercase tracking-wide text-slate-400">
                    Last Seen
                  </th>
                </tr>
              </thead>

              <tbody>
                {loading ? (
                  <tr>
                    <td
                      colSpan="6"
                      className="px-4 py-10 text-center text-sm font-semibold text-slate-500"
                    >
                      Loading contacts...
                    </td>
                  </tr>
                ) : filteredContacts.length === 0 ? (
                  <tr>
                    <td
                      colSpan="6"
                      className="px-4 py-10 text-center text-sm font-semibold text-slate-500"
                    >
                      No contacts found.
                    </td>
                  </tr>
                ) : (
                  filteredContacts.map((contact) => (
                    <tr
                      key={contact.id}
                      className="border-b border-slate-100 hover:bg-slate-50"
                    >
                      <td className="px-4 py-4">
                        <div className="flex items-center gap-3">
                          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-purple-100 text-sm font-extrabold text-purple-700">
                            {(contact.name || "U").slice(0, 1).toUpperCase()}
                          </div>
                          <div>
                            <p className="text-sm font-extrabold text-slate-900">
                              {contact.name || "Unknown Customer"}
                            </p>
                            <p className="text-xs text-slate-400">
                              ID: {contact.id}
                            </p>
                          </div>
                        </div>
                      </td>

                      <td className="px-4 py-4">
                        <div className="space-y-1">
                          <p className="flex items-center gap-2 text-sm font-semibold text-slate-700">
                            <Phone className="h-4 w-4 text-slate-400" />
                            {contact.phone || "-"}
                          </p>
                          <p className="flex items-center gap-2 text-sm text-slate-500">
                            <Mail className="h-4 w-4 text-slate-400" />
                            {contact.email || "-"}
                          </p>
                        </div>
                      </td>

                      <td className="px-4 py-4">
                        <span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-700">
                          {contact.source || "public_chat"}
                        </span>
                      </td>

                      <td className="max-w-[330px] px-4 py-4">
                        <p className="line-clamp-2 flex items-start gap-2 text-sm text-slate-600">
                          <MessageSquare className="mt-0.5 h-4 w-4 shrink-0 text-slate-400" />
                          {contact.last_message || contact.first_message || "-"}
                        </p>
                      </td>

                      <td className="px-4 py-4">
                        <span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">
                          {contact.status || "new"}
                        </span>
                      </td>

                      <td className="px-4 py-4 text-sm font-semibold text-slate-500">
                        {formatTime(contact.last_seen_at || contact.created_at)}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}