import React, { useEffect, useMemo, useState } from "react";
import { Copy, KeyRound, Link, Loader2, Plus, Save, ShieldCheck } from "lucide-react";
import AgentSteps from "./training/AgentSteps";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://localhost:8000";

function getTenantSlug() {
  return localStorage.getItem("tenant_slug") || "t1";
}

function makeCallbackUrl(tenantSlug) {
  const base = API_BASE_URL.replace(/\/$/, "");
  return `${base}/webhook/whatsapp/${tenantSlug}`;
}

function Field({ label, value, onChange, placeholder, type = "text", secret = false }) {
  return (
    <label className="block">
      <span className="mb-2 block text-xs font-bold uppercase tracking-wide text-slate-500">{label}</span>
      <input
        type={secret ? "password" : type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="h-12 w-full rounded-xl border border-slate-200 bg-white px-4 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
      />
    </label>
  );
}

export default function Step3() {
  const tenantSlug = useMemo(() => getTenantSlug(), []);
  const callbackUrl = useMemo(() => makeCallbackUrl(tenantSlug), [tenantSlug]);

  const [provider, setProvider] = useState("twilio");
  const [verifyToken, setVerifyToken] = useState(`verify_${tenantSlug}_123`);
  const [twilioSid, setTwilioSid] = useState("");
  const [twilioToken, setTwilioToken] = useState("");
  const [twilioPhone, setTwilioPhone] = useState("");
  const [metaToken, setMetaToken] = useState("");
  const [metaPhoneId, setMetaPhoneId] = useState("");
  const [metaBusinessId, setMetaBusinessId] = useState("");
  const [whatsappNumber, setWhatsappNumber] = useState("");
  const [status, setStatus] = useState({ type: "", message: "" });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("auth_token");
    if (!token) return;
    fetch(`${API_BASE_URL}/tenant/whatsapp-config`, {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((r) => r.json())
      .then((res) => {
        const cfg = res?.config || {};
        if (cfg.whatsapp_provider) setProvider(cfg.whatsapp_provider);
        if (cfg.twilio_phone_number) setTwilioPhone(cfg.twilio_phone_number);
        if (cfg.whatsapp_number) setWhatsappNumber(cfg.whatsapp_number);
        if (cfg.whatsapp_verify_token) setVerifyToken(cfg.whatsapp_verify_token);
        if (cfg.meta_phone_number_id) setMetaPhoneId(cfg.meta_phone_number_id);
        if (cfg.meta_business_account_id) setMetaBusinessId(cfg.meta_business_account_id);
      })
      .catch(() => {});
  }, []);

  const copyText = async (text) => {
    try { await navigator.clipboard.writeText(text); } catch {}
  };

  const saveConnection = async () => {
    const token = localStorage.getItem("auth_token");
    setStatus({ type: "", message: "" });

    if (!token) {
      setStatus({ type: "error", message: "Please login again." });
      return;
    }
    if (provider === "twilio" && (!twilioSid.trim() || !twilioToken.trim() || !twilioPhone.trim())) {
      setStatus({ type: "error", message: "Twilio SID, Auth Token and WhatsApp number are required." });
      return;
    }
    if (provider === "meta" && (!metaPhoneId.trim() || !metaToken.trim())) {
      setStatus({ type: "error", message: "Meta access token and phone number ID are required." });
      return;
    }

    try {
      setLoading(true);
      const response = await fetch(`${API_BASE_URL}/tenant/whatsapp-config`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          provider,
          twilio_account_sid: twilioSid,
          twilio_auth_token: twilioToken,
          twilio_phone_number: twilioPhone,
          meta_access_token: metaToken,
          meta_phone_number_id: metaPhoneId,
          meta_business_account_id: metaBusinessId,
          whatsapp_number: whatsappNumber || twilioPhone,
          whatsapp_verify_token: verifyToken,
        agent_type: localStorage.getItem("selected_agent_type") || "chat",
        }),
      });
      const result = await response.json().catch(() => null);
      if (!response.ok) throw new Error(result?.detail || result?.message || "Connection save failed.");
      setStatus({ type: "success", message: "WhatsApp connection saved. Use the callback URL in Twilio/Meta webhook settings." });
    } catch (err) {
      setStatus({ type: "error", message: err.message || "Something went wrong." });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-[calc(100vh-72px)] bg-[#f6f8fc]">
      <div className="border-b border-slate-100 bg-white px-6 py-5 lg:px-8">
        <div className="flex items-center justify-between">
          <button className="inline-flex items-center gap-3 text-[16px] font-bold text-slate-900">
            <Plus className="h-5 w-5 text-purple-600" /> Create New Agent
          </button>
          <p className="text-xs font-semibold text-slate-400">Step 5 of 5</p>
        </div>
      </div>

      <AgentSteps current={5} />

      <section className="mx-auto max-w-5xl px-5 py-10">
        <div className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
          <div className="flex items-start gap-4">
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-purple-100 text-purple-600">
              <ShieldCheck className="h-6 w-6" />
            </div>
            <div>
              <h2 className="text-xl font-extrabold text-slate-950">Connect WhatsApp / Twilio</h2>
              <p className="mt-1 text-sm leading-6 text-slate-500">
                Save tenant-specific WhatsApp credentials. Customers can use /chat/{tenantSlug} or /chat_{tenantSlug}.
              </p>
            </div>
          </div>

          <div className="mt-7 rounded-2xl border border-purple-100 bg-purple-50/40 p-5">
            <label className="block">
              <span className="mb-2 block text-xs font-bold uppercase tracking-wide text-slate-500">Provider</span>
              <select value={provider} onChange={(e) => setProvider(e.target.value)} className="h-12 w-full rounded-xl border border-slate-200 bg-white px-4 text-sm outline-none">
                <option value="twilio">Twilio WhatsApp</option>
                <option value="meta">Meta WhatsApp Cloud API</option>
              </select>
            </label>
          </div>

          <div className="mt-6 grid gap-5 md:grid-cols-2">
            <div>
              <label className="mb-2 block text-xs font-bold uppercase tracking-wide text-slate-500">Callback URL</label>
              <div className="flex gap-2">
                <input readOnly value={callbackUrl} className="h-12 flex-1 rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm text-slate-600" />
                <button onClick={() => copyText(callbackUrl)} className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-4 text-sm font-bold text-purple-600">
                  <Copy className="h-4 w-4" /> Copy
                </button>
              </div>
            </div>
            <Field label="Verify Token" value={verifyToken} onChange={setVerifyToken} placeholder="verify token" />
          </div>

          {provider === "twilio" ? (
            <div className="mt-6 grid gap-5 md:grid-cols-2">
              <Field label="Twilio Account SID" value={twilioSid} onChange={setTwilioSid} placeholder="ACxxxxxxxxxxxx" />
              <Field label="Twilio Auth Token" value={twilioToken} onChange={setTwilioToken} placeholder="Auth token" secret />
              <Field label="Twilio WhatsApp From Number" value={twilioPhone} onChange={setTwilioPhone} placeholder="+14155238886 or +91..." />
              <Field label="Business WhatsApp Number" value={whatsappNumber} onChange={setWhatsappNumber} placeholder="Optional display number" />
            </div>
          ) : (
            <div className="mt-6 grid gap-5 md:grid-cols-2">
              <Field label="Meta Access Token" value={metaToken} onChange={setMetaToken} placeholder="Permanent access token" secret />
              <Field label="Meta Phone Number ID" value={metaPhoneId} onChange={setMetaPhoneId} placeholder="Phone number ID" />
              <Field label="Meta Business Account ID" value={metaBusinessId} onChange={setMetaBusinessId} placeholder="Business account ID" />
              <Field label="Business WhatsApp Number" value={whatsappNumber} onChange={setWhatsappNumber} placeholder="+91..." />
            </div>
          )}

          {status.message && (
            <div className={`mt-5 rounded-xl px-4 py-3 text-sm font-semibold ${status.type === "success" ? "bg-emerald-50 text-emerald-700" : "bg-red-50 text-red-700"}`}>
              {status.message}
            </div>
          )}

          <div className="mt-8 flex items-center justify-between">
            <button onClick={() => (window.location.href = "/review-agent")} className="rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-bold text-slate-600 shadow-sm">
              ← Back
            </button>
            <button onClick={saveConnection} disabled={loading} className="inline-flex items-center gap-2 rounded-xl bg-purple-500 px-7 py-3 text-sm font-bold text-white shadow-sm hover:bg-purple-600 disabled:opacity-60">
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />} Save Connection
            </button>
          </div>
        </div>
      </section>
    </div>
  );
}
