import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  ArrowLeft,
  Bot,
  Loader2,
  MessageCircle,
  RefreshCcw,
  Send,
  User,
} from "lucide-react";

const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL || "http://localhost:8000";

function getPathValue() {
  return window.location.pathname || "/";
}

function normalizeAgentType(value) {
  return value === "product" ? "product" : "chat";
}

function getInitialTenantSlug() {
  const path = getPathValue();

  const slashMatch = path.match(/^\/chat\/([^/]+)/);
  if (slashMatch?.[1]) return slashMatch[1];

  const underscoreMatch = path.match(/^\/chat_([^/]+)/);
  if (underscoreMatch?.[1]) return underscoreMatch[1];

  return localStorage.getItem("public_chat_tenant_slug") || "public";
}

function buildWelcomeText() {
   return "Loading assistant...";
}

async function getTenantActiveAgentType(tenantSlug) {
  try {
    const res = await fetch(
      `${API_BASE_URL}/tenant/active-agent-type/${encodeURIComponent(tenantSlug)}`
    );

    const data = await res.json().catch(() => null);

    if (!res.ok || !data?.success) {
      return "chat";
    }

    return normalizeAgentType(data.active_agent_type || data.agent_type || "chat");
  } catch {
    return "chat";
  }
}

async function resolveChatRoute() {
  const path = getPathValue();

  if (path.startsWith("/chat_") || path.startsWith("/chat/")) {
    const tenantSlug = getInitialTenantSlug();
    const agentType = await getTenantActiveAgentType(tenantSlug);

    localStorage.setItem("public_chat_tenant_slug", tenantSlug);
    localStorage.setItem("public_chat_agent_type", agentType);

    return {
      tenantSlug,
      agentType,
      chatApiPath: path,
    };
  }

  const publicName = path.replace(/^\/+/, "").split("/")[0];

  const res = await fetch(
    `${API_BASE_URL}/public-link/resolve/${encodeURIComponent(publicName)}`
  );

  const data = await res.json().catch(() => null);

  if (!res.ok || !data?.success) {
    throw new Error(data?.detail || "Public link not found.");
  }

  const tenantSlug = data.tenant_slug || "public";
  const agentType = normalizeAgentType(
    data.active_agent_type || data.agent_type || data.type || "chat"
  );
  const chatApiPath = data.redirect_path || data.target_path || `/chat_${tenantSlug}`;

  localStorage.setItem("public_chat_tenant_slug", tenantSlug);
  localStorage.setItem("public_chat_agent_type", agentType);

  return {
    tenantSlug,
    agentType,
    chatApiPath,
  };
}

function makeSessionId(tenantSlug, agentType = "chat") {
  const key = `agent_chat_session_id_${agentType}_${tenantSlug}`;
  const old = localStorage.getItem(key);
  if (old) return old;

  const id = `session_${agentType}_${tenantSlug}_${Date.now()}_${Math.random()
    .toString(16)
    .slice(2)}`;
  localStorage.setItem(key, id);
  return id;
}

function getCustomerStorageKey(agentType, tenantSlug) {
  return `public_chat_customer_${agentType}_${tenantSlug}`;
}

function loadSavedCustomer(agentType, tenantSlug) {
  try {
    return JSON.parse(localStorage.getItem(getCustomerStorageKey(agentType, tenantSlug)) || "{}");
  } catch {
    return {};
  }
}

function timeNow() {
  return new Date().toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
  });
}

function isValidPhone(value) {
  const digits = String(value || "").replace(/\D/g, "");
  return digits.length >= 7 && digits.length <= 15;
}

function toArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.filter(Boolean);
  return [value].filter(Boolean);
}

function getChatAssets(result, agentType = "chat") {
  const images = [
    ...toArray(result?.images),
    ...toArray(result?.image_urls),
    ...toArray(result?.assets?.images),
  ];

  // For Chat Agent, do not auto-render backend sources as "View source" buttons.
  // If the user asks for a website/product/contact link, backend should include the URL in answer text,
  // and renderMessageWithLinks() will make it clickable naturally.
  if (agentType !== "product") {
    return {
      images: [...new Set(images.map((item) => String(item).trim()).filter(Boolean))],
      links: [],
    };
  }

  // Product Agent keeps the existing source/link rendering behavior unchanged.
  const links = [
    ...toArray(result?.links),
    ...toArray(result?.link_urls),
    ...toArray(result?.assets?.links),
    ...toArray(result?.sources),
    ...toArray(result?.assets?.sources),
  ];

  return {
    images: [...new Set(images.map((item) => String(item).trim()).filter(Boolean))],
    links: [...new Set(links.map((item) => String(item).trim()).filter(Boolean))],
  };
}

function isValidImageUrl(url) {
  return /^https?:\/\//i.test(String(url || ""));
}

function isValidLinkUrl(url) {
  return /^https?:\/\//i.test(String(url || ""));
}

function getProductBotText(result) {
  if (Array.isArray(result?.responses) && result.responses.length) {
    return result.responses.join("\n\n");
  }

  return result?.answer || result?.message || "I could not create an answer.";
}

function extractPhone(value) {
  const match = String(value || "").match(/(\+?\d[\d\s-]{6,18}\d)/);
  return match ? match[1].replace(/[^\d+]/g, "") : "";
}

function extractName(value, phone) {
  return String(value || "")
    .replace(phone, "")
    .replace(/[0-9+()\-\s]{7,}/g, "")
    .replace(/[,|:]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}


const DEFAULT_WIDGET_SETTINGS = {
  theme_config: {
    primary_color: "#7c3aed",
    secondary_color: "#ede9fe",
    background_color: "#ffffff",
    text_color: "#0f172a",
  },
  widget_config: {
    font_family: "System Default",
    widget_position: "bottom_right",
    offset_horizontal: 20,
    offset_vertical: 20,
    button_effect: "none",
  },
  behavior_config: {
    show_handoff_cta: true,
    show_online_badge: true,
  },
};

function mergeWidgetSettings(settings = {}) {
  return {
    ...DEFAULT_WIDGET_SETTINGS,
    ...settings,
    theme_config: {
      ...DEFAULT_WIDGET_SETTINGS.theme_config,
      ...(settings.theme_config || {}),
    },
    widget_config: {
      ...DEFAULT_WIDGET_SETTINGS.widget_config,
      ...(settings.widget_config || {}),
    },
    behavior_config: {
      ...DEFAULT_WIDGET_SETTINGS.behavior_config,
      ...(settings.behavior_config || {}),
    },
  };
}

async function fetchPublicWidgetSettings(tenantSlug, agentType) {
  try {
    const response = await fetch(
      `${API_BASE_URL}/public-agent-widget-settings/${encodeURIComponent(
        tenantSlug
      )}?agent_type=${encodeURIComponent(agentType)}`
    );

    const data = await response.json().catch(() => null);
    if (!response.ok || !data?.settings) {
      return DEFAULT_WIDGET_SETTINGS;
    }

    return mergeWidgetSettings(data.settings);
  } catch {
    return DEFAULT_WIDGET_SETTINGS;
  }
}

function renderMessageWithLinks(text, isUser = false) {
  if (!text) return null;

  const urlRegex = /(https?:\/\/[^\s]+)/g;

  return String(text).split(urlRegex).map((part, index) => {
    if (urlRegex.test(part)) {
      return (
        <a
          key={index}
          href={part}
          target="_blank"
          rel="noopener noreferrer"
          className={`underline break-all ${
            isUser
              ? "text-white font-semibold"
              : "text-blue-600 font-semibold"
          }`}
        >
          {part}
        </a>
      );
    }

    return <React.Fragment key={index}>{part}</React.Fragment>;
  });
}
export default function ChatBot() {
  const bottomRef = useRef(null);

  const [tenantSlug, setTenantSlug] = useState(() => getInitialTenantSlug());
  const [agentType, setAgentType] = useState("chat");
  const [chatApiPath, setChatApiPath] = useState(() => getPathValue());
  const [routeReady, setRouteReady] = useState(false);

  const [sessionId, setSessionId] = useState(() =>
    makeSessionId(getInitialTenantSlug(), "chat")
  );

  const customerKey = getCustomerStorageKey(agentType, tenantSlug);

  const savedCustomer = useMemo(() => {
    try {
      return JSON.parse(localStorage.getItem(customerKey) || "{}");
    } catch {
      return {};
    }
  }, [customerKey]);

  const [customerName, setCustomerName] = useState(savedCustomer.name || "");
  const [customerPhone, setCustomerPhone] = useState(savedCustomer.phone || "");
  // const [step, setStep] = useState(
  //   savedCustomer.name && savedCustomer.phone ? "chat" : "name"
  // );
  const [step, setStep] = useState(
  savedCustomer.name && savedCustomer.phone ? "chat" : "lead"
);

  const [message, setMessage] = useState("");
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState("");
  const [welcomeMessage, setWelcomeMessage] = useState("Hi! How can I help you today?");
  const [starterQuestions, setStarterQuestions] = useState([]);
  // const [widgetSettings, setWidgetSettings] = useState(DEFAULT_WIDGET_SETTINGS);
  const [widgetSettings, setWidgetSettings] = useState(null);

  const [messages, setMessages] = useState([
    {
      id: "welcome_loading",
      role: "bot",
      text: "Loading assistant...",
      time: timeNow(),
    },
  ]);

  const canSend = useMemo(
    () => message.trim() && !isSending && routeReady,
    [message, isSending, routeReady]
  );

  useEffect(() => {
    async function setupRoute() {
      try {
        const resolved = await resolveChatRoute();

        setTenantSlug(resolved.tenantSlug);
        setAgentType(resolved.agentType);
        setChatApiPath(resolved.chatApiPath);

        const newSessionId = makeSessionId(
          resolved.tenantSlug,
          resolved.agentType
        );
        setSessionId(newSessionId);

        const resolvedSavedCustomer = loadSavedCustomer(resolved.agentType, resolved.tenantSlug);
        const hasResolvedCustomer = Boolean(resolvedSavedCustomer.name && resolvedSavedCustomer.phone);
        setCustomerName(resolvedSavedCustomer.name || "");
        setCustomerPhone(resolvedSavedCustomer.phone || "");

        const savedWidgetSettings = await fetchPublicWidgetSettings(
          resolved.tenantSlug,
          resolved.agentType
        );
        setWidgetSettings(savedWidgetSettings);

        const welcomeUrl =
          resolved.agentType === "product"
            ? `${API_BASE_URL}/product-query/public-chat/${resolved.tenantSlug}`
            : `${API_BASE_URL}${resolved.chatApiPath}`;

        const welcomeBody =
          resolved.agentType === "product"
            ? {
                query: "__welcome__",
                session_id: newSessionId,
              }
            : {
                message: "__welcome__",
                session_id: newSessionId,
                top_k: 5,
              };

        let welcomeText = buildWelcomeText();
        let welcomeQuickReplies = [];

        try {
          const welcomeRes = await fetch(welcomeUrl, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(welcomeBody),
          });

          const welcomeData = await welcomeRes.json().catch(() => null);

          if (welcomeRes.ok) {
            welcomeText =
              resolved.agentType === "product"
                ? getProductBotText(welcomeData)
                : welcomeData?.answer || "Hi! How can I help you today?";

            const savedStarterQuestions = toArray(
              welcomeData?.starter_questions
            )
              .map((q) =>
                typeof q === "string"
                  ? q
                  : q?.label || q?.text || ""
              )
              .filter(Boolean);
            welcomeQuickReplies = savedStarterQuestions;
            setStarterQuestions(savedStarterQuestions);

            if (welcomeData?.tenant_name) {
              localStorage.setItem("tenant_name", welcomeData.tenant_name);
            }
          } else {
            welcomeText =
              resolved.agentType === "product"
                ? "Hi! How can I help you today?"
                : "Hi! How can I help you today?";
            setStarterQuestions([]);
          }
        } catch {
          welcomeText =
            resolved.agentType === "product"
              ? "Hi! How can I help you today?"
              : "Hi! How can I help you today?";
          welcomeQuickReplies = [];
          setStarterQuestions([]);
        }

        setWelcomeMessage(welcomeText);

        if (resolved.agentType === "product") {
          setStep("chat");
          setMessages([
            {
              id: "welcome_dynamic",
              role: "bot",
              text: welcomeText,
              time: timeNow(),
              quickReplies: welcomeQuickReplies,
            },
          ]);
        } else if (hasResolvedCustomer) {
          setStep("chat");
          setMessages([
            {
              id: "welcome_dynamic",
              role: "bot",
              text: welcomeText,
              time: timeNow(),
              quickReplies: welcomeQuickReplies,
            },
          ]);
        } else {
          setStep("lead");
            setMessages([
              {
                id: "ask_lead",
                role: "bot",
                text: "Please enter your name and phone number to start chat.",
                time: timeNow(),
              },
            ]);
          // setStep("name");
          // setMessages([
          //   {
          //     id: "ask_name",
          //     role: "bot",
          //     text: "Please enter your name to start chat.",
          //     time: timeNow(),
          //   },
          // ]);
        }

        setRouteReady(true);
        setError("");
      } catch (err) {
        const msg = err.message || "Public chat link is invalid.";
        setError(msg);
        setRouteReady(false);
        setMessages((prev) => [
          ...prev,
          {
            id: `route_error_${Date.now()}`,
            role: "bot",
            text: msg,
            time: timeNow(),
            isError: true,
          },
        ]);
      }
    }

    setupRoute();
  }, []);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isSending]);

  const saveCustomerLocal = (name, phone) => {
    localStorage.setItem(customerKey, JSON.stringify({ name, phone }));
  };

  const resetChat = () => {
    const key = `agent_chat_session_id_${agentType}_${tenantSlug}`;
    const id = `session_${agentType}_${tenantSlug}_${Date.now()}_${Math.random()
      .toString(16)
      .slice(2)}`;

    localStorage.setItem(key, id);
    localStorage.removeItem(customerKey);

    // Keep Redis/backend session flow clean: new session_id + fresh backend welcome.
    window.location.reload();
    return;
  };

  const addUserMessage = (text) => {
    setMessages((prev) => [
      ...prev,
      {
        id: `u_${Date.now()}`,
        role: "user",
        text,
        time: timeNow(),
      },
    ]);
  };

  const addBotMessage = (text, isError = false, assets = {}, quickReplies = []) => {
    setMessages((prev) => [
      ...prev,
      {
        id: `b_${Date.now()}_${Math.random()}`,
        role: "bot",
        text,
        time: timeNow(),
        isError,
        images: toArray(assets.images),
        links: toArray(assets.links),
        quickReplies: toArray(quickReplies),
      },
    ]);
  };

  const saveCustomerToBackend = async (phone, name = customerName) => {
    try {
      await fetch(`${API_BASE_URL}/public-chat/customer/${tenantSlug}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          message: `${
            agentType === "product" ? "Product bot" : "Chat bot"
          } customer registered from public chat`,
          session_id: sessionId,
          customer_name: name,
          customer_phone: phone,
          customer_email: "",
          agent_type: agentType,
        }),
      });
    } catch {
      // Do not block the chat UI if only contact pre-save fails.
    }
  };

  const sendMessage = async (quickReplyText = "") => {
    const clean = String(quickReplyText || message).trim();
    if (!clean || isSending || !routeReady) return;

    addUserMessage(clean);
    setMessage("");
    setError("");

    if (step === "lead") {
    const phone = extractPhone(clean);
    const name = extractName(clean, phone);

    if (!name || !isValidPhone(phone)) {
      addBotMessage(
        "Please enter both name and phone number. Example: Aarju 9876543210",
        true
      );
      return;
    }

    setCustomerName(name);
    setCustomerPhone(phone);
    saveCustomerLocal(name, phone);
    await saveCustomerToBackend(phone, name);

    setStep("chat");
    addBotMessage(welcomeMessage, false, {}, starterQuestions);
    return;
  }

    try {
      setIsSending(true);

      const url =
        agentType === "product"
          ? `${API_BASE_URL}/product-query/public-chat/${tenantSlug}`
          : `${API_BASE_URL}${chatApiPath}`;

      const body =
        agentType === "product"
          ? {
              query: clean,
              session_id: sessionId,
              customer_name: customerName,
              customer_phone: customerPhone,
            }
          : {
              message: clean,
              session_id: sessionId,
              top_k: 5,
              customer_name: customerName,
              customer_phone: customerPhone,
            };

      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(
          result?.detail || result?.message || `Chat failed: ${response.status}`
        );
      }

      if (result?.session_id && result.session_id !== sessionId) {
        const key = `agent_chat_session_id_${agentType}_${tenantSlug}`;
        localStorage.setItem(key, result.session_id);
        setSessionId(result.session_id);
      }

      const assets = getChatAssets(result, agentType);

      addBotMessage(
        agentType === "product"
          ? getProductBotText(result)
          : result?.answer || result?.message || "I could not create an answer.",
        false,
        assets
      );
    } catch (err) {
      const msg = err.message || "Something went wrong while chatting.";
      setError(msg);
      addBotMessage(msg, true);
    } finally {
      setIsSending(false);
    }
  };

  const onKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };
  if (!widgetSettings) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white text-slate-700">
        Loading assistant...
      </div>
    );
  }
  const theme = widgetSettings.theme_config || DEFAULT_WIDGET_SETTINGS.theme_config;
  const widget = widgetSettings.widget_config || DEFAULT_WIDGET_SETTINGS.widget_config;
  const behavior = widgetSettings.behavior_config || DEFAULT_WIDGET_SETTINGS.behavior_config;
  const selectedFont = widget.font_family === "System Default" ? undefined : widget.font_family;
  const pageBackground = theme.background_color || "#f8fafc";
  const softBackground = theme.secondary_color || "#eef2ff";
  const primaryColor = theme.primary_color || "#7c3aed";
  const textColor = theme.text_color || "#0f172a";

  return (
    <div
      className="min-h-screen text-slate-900"
      style={{ background: pageBackground, color: textColor, fontFamily: selectedFont }}
    >
      <main className="mx-auto flex min-h-screen max-w-5xl flex-col px-3 py-4 sm:px-6">
        <div className="overflow-hidden rounded-3xl bg-white shadow-sm ring-1 ring-slate-200">
          <header
            className="flex items-center justify-between px-4 py-4 text-white sm:px-6"
            style={{ background: primaryColor }}
          >
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={() => (window.location.href = "/")}
                className="rounded-full p-2 hover:bg-white/10"
              >
                <ArrowLeft className="h-5 w-5" />
              </button>

              <div className="flex h-11 w-11 items-center justify-center rounded-full bg-white/15">
                <MessageCircle className="h-6 w-6" />
              </div>

              <div>
                <h2 className="text-base font-bold sm:text-lg">
                  {agentType === "product"
                    ? "Product Assistant"
                    : "Chat Assistant"}
                </h2>
                <p className="text-xs text-white/80">
                {agentType === "product"
                  ? "Product Bot"
                  : ""}
              </p>
              </div>
            </div>

            <button
              type="button"
              onClick={resetChat}
              className="inline-flex items-center gap-2 rounded-xl bg-white/10 px-3 py-2 text-xs font-bold hover:bg-white/20"
            >
              <RefreshCcw className="h-4 w-4" /> New Chat
            </button>
          </header>

          <section
            className="h-[calc(100vh-190px)] min-h-[520px] overflow-y-auto px-3 py-5 sm:px-6"
            style={{ background: `linear-gradient(135deg, ${pageBackground} 0%, ${softBackground} 100%)` }}
          >
            <div className="space-y-4">
              {messages.map((item) => {
                const isUser = item.role === "user";

                return (
                  <div
                    key={item.id}
                    className={`flex items-end gap-2 ${
                      isUser ? "justify-end" : "justify-start"
                    }`}
                  >
                    {!isUser && (
                      <div
                        className="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full bg-white shadow-sm"
                        style={{ color: primaryColor }}
                      >
                        <Bot className="h-4 w-4" />
                      </div>
                    )}

                    <div
                      className={`max-w-[82%] rounded-2xl px-4 py-3 text-sm leading-6 shadow-sm sm:max-w-[70%] ${
                        isUser
                          ? "rounded-br-sm text-white"
                          : item.isError
                          ? "rounded-bl-sm border border-red-200 bg-red-50 text-red-700"
                          : "rounded-bl-sm bg-white text-slate-700"
                      }`}
                      style={isUser ? { background: primaryColor } : undefined}
                    >
                      <p
                    className={`whitespace-pre-wrap ${
                      agentType === "product" ? "font-mono text-[14px]" : ""
                    }`}
                  >
                    {/* {item.text.split("\n").map((line, idx) => {
                      const isLink = line.startsWith("http://") || line.startsWith("https://");

                      if (isLink) {
                        return (
                          <a
                            key={idx}
                            href={line.trim()}
                            target="_blank"
                            rel="noreferrer"
                            className="text-blue-600 underline break-all block"
                          >
                            {line}
                          </a>
                        );
                      }

                      return <div key={idx}>{line}</div>;
                    })} */}

                    {item.text.split("\n").map((line, idx) => (
                        <div key={idx}>
                          {renderMessageWithLinks(line, isUser)}
                        </div>
                      ))}
                  </p>

                      {!isUser && item.quickReplies?.length > 0 && (
                        <div className="mt-3 flex flex-wrap gap-2">
                          {item.quickReplies.map((question, index) => (
                            <button
                              key={`${question}-${index}`}
                              type="button"
                              onClick={() => sendMessage(question)}
                              disabled={isSending || !routeReady}
                              className="rounded-full border px-3 py-1.5 text-xs font-semibold disabled:cursor-not-allowed disabled:opacity-50"
                              style={{ borderColor: primaryColor, background: softBackground, color: primaryColor }}
                            >
                              {question}
                            </button>
                          ))}
                        </div>
                      )}

                      {!isUser && item.images?.length > 0 && (
                        <div className="chat-image-grid">
                          {item.images.filter(isValidImageUrl).map((url, index) => (
                            <a
                              key={`${url}-${index}`}
                              href={url}
                              target="_blank"
                              rel="noreferrer"
                              className="chat-image-link"
                            >
                              <img
                                src={url}
                                alt={`Product ${index + 1}`}
                                className="chat-product-image"
                                loading="lazy"
                              />
                            </a>
                          ))}
                        </div>
                      )}

                      {agentType === "product" && !isUser && item.links?.length > 0 && (
                        <div className="chat-link-list">
                          {item.links.filter(isValidLinkUrl).map((url, index) => (
                            <a
                              key={`${url}-${index}`}
                              href={url}
                              target="_blank"
                              rel="noreferrer"
                              className="chat-source-link"
                            >
                              View source {index + 1}
                            </a>
                          ))}
                        </div>
                      )}

                      <div
                        className={`mt-1 text-right text-[10px] ${
                          isUser ? "text-purple-100" : "text-slate-400"
                        }`}
                      >
                        {item.time}
                      </div>
                    </div>

                    {isUser && (
                      <div
                        className="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full text-white shadow-sm"
                        style={{ background: primaryColor }}
                      >
                        <User className="h-4 w-4" />
                      </div>
                    )}
                  </div>
                );
              })}

              {isSending && (
                <div className="flex items-center gap-2 text-sm text-slate-500">
                  <Loader2 className="h-4 w-4 animate-spin" /> Assistant is
                  typing...
                </div>
              )}

              <div ref={bottomRef} />
            </div>
          </section>

          {error && (
            <div className="border-t border-red-100 bg-red-50 px-4 py-2 text-sm text-red-700">
              {error}
            </div>
          )}

          <footer className="border-t border-slate-200 bg-white p-3 sm:p-4">
            <div className="flex items-end gap-2 rounded-2xl border border-slate-200 bg-slate-50 p-2 focus-within:ring-2" style={{ '--tw-ring-color': softBackground }}>
              <textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                onKeyDown={onKeyDown}
                placeholder={
                  step === "lead"
                    ? "Enter your name and phone number"
                    : routeReady
                    ? agentType === "product"
                      ? "Choose an option or type your message..."
                      : "Type your message..."
                    : "Loading chat..."
                }
                rows={1}
                className="max-h-32 min-h-[42px] flex-1 resize-none bg-transparent px-3 py-2 text-sm outline-none placeholder:text-slate-400"
              />

              <button
                type="button"
                onClick={sendMessage}
                disabled={!canSend}
                className="inline-flex h-11 w-11 flex-shrink-0 items-center justify-center rounded-2xl text-white shadow-sm disabled:cursor-not-allowed disabled:opacity-50"
                style={{ background: primaryColor }}
              >
                {isSending ? (
                  <Loader2 className="h-5 w-5 animate-spin" />
                ) : (
                  <Send className="h-5 w-5" />
                )}
              </button>
            </div>
          </footer>
        </div>
      </main>
    </div>
  );
}
