import React, { useEffect, useState } from "react";
import {
  Loader2,
  Lock,
  Mail,
  Sparkles,
  Eye,
  EyeOff,
} from "lucide-react";

const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL || "http://localhost:8000";

export default function SignIn() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);

  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const savedRemember = localStorage.getItem("remember_me") === "true";
    const savedEmail = localStorage.getItem("remembered_email") || "";

    if (savedRemember) {
      setRememberMe(true);
      setEmail(savedEmail);
    }
  }, []);

  const canSubmit = email.trim() && password.trim() && !isLoading;

  const handleLogin = async () => {
    setError("");

    if (!email.trim() || !password.trim()) {
      setError("Please enter email and password.");
      return;
    }

    try {
      setIsLoading(true);

      const response = await fetch(`${API_BASE_URL}/auth/login`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: email.trim(),
          password,
        }),
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(result?.detail || "Login failed.");
      }

      localStorage.setItem("auth_token", result.token);
      localStorage.setItem("tenant_slug", result.tenant.slug);
      localStorage.setItem("tenant_id", String(result.tenant.id));
      localStorage.setItem("user_email", result.user.email);

      // Show tenant name from tenants.tenant_name in Sidebar and TopNav
      localStorage.setItem("tenant_name", result.tenant?.tenant_name || "");
      localStorage.setItem(
        "user_name",
        result.tenant?.tenant_name || result.user?.name || ""
      );
      

      if (rememberMe) {
        localStorage.setItem("remember_me", "true");
        localStorage.setItem("remembered_email", email.trim());
      } else {
        localStorage.removeItem("remember_me");
        localStorage.removeItem("remembered_email");
      }

      window.location.href = "/agent-type";
    } catch (err) {
      setError(err.message || "Something went wrong.");
    } finally {
      setIsLoading(false);
    }
  };

  const onKeyDown = (e) => {
    if (e.key === "Enter") {
      handleLogin();
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center px-4">
      <div className="w-full max-w-md rounded-3xl bg-white p-8 shadow-sm ring-1 ring-slate-200">
        <div className="text-center">
          <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-3xl bg-purple-100">
            <Sparkles className="h-8 w-8 text-purple-600" />
          </div>

          <h1 className="text-2xl font-extrabold text-slate-900">
            Sign in to AI Agent
          </h1>

          <p className="mt-2 text-sm text-slate-500">
            Login with your registered company email.
          </p>
        </div>

        <div className="mt-8 space-y-4">
          <label className="block">
            <span className="mb-2 block text-sm font-semibold text-slate-700">
              Email
            </span>

            <div className="flex items-center rounded-xl border border-slate-200 bg-white px-4 py-3 focus-within:border-[var(--primary-color)] focus-within:ring-2 focus-within:ring-purple-100">
              <Mail className="mr-3 h-5 w-5 text-slate-400" />

              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onKeyDown={onKeyDown}
                placeholder="you@company.com"
                className="w-full bg-transparent outline-none"
              />
            </div>
          </label>

          <label className="block">
            <span className="mb-2 block text-sm font-semibold text-slate-700">
              Password
            </span>

            <div className="flex items-center rounded-xl border border-slate-200 bg-white px-4 py-3 focus-within:border-[var(--primary-color)] focus-within:ring-2 focus-within:ring-purple-100">
              <Lock className="mr-3 h-5 w-5 text-slate-400" />

              <input
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                onKeyDown={onKeyDown}
                placeholder="Enter password"
                className="w-full bg-transparent outline-none"
              />

              <button
                type="button"
                onClick={() => setShowPassword((prev) => !prev)}
                className="ml-2 text-purple-600"
              >
                {showPassword ? (
                  <EyeOff className="h-5 w-5" />
                ) : (
                  <Eye className="h-5 w-5" />
                )}
              </button>
            </div>
          </label>

          <div className="flex items-center justify-between">
            <label className="flex items-center text-sm font-medium text-slate-700">
              <input
                type="checkbox"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
                className="mr-2"
              />
              Remember Me
            </label>

            <button
              type="button"
              onClick={() => {
                window.location.href = "/forgot-password";
              }}
              className="text-sm font-medium text-purple-600 underline"
            >
              Forgot Password?
            </button>
          </div>

          {error && (
            <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
              {error}
            </div>
          )}

          <button
            type="button"
            onClick={handleLogin}
            disabled={!canSubmit}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-purple-600 px-5 py-3 font-bold text-white shadow-sm hover:bg-[var(--btn-hover-color)] disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isLoading ? (
              <>
                <Loader2 className="h-5 w-5 animate-spin" />
                Signing in...
              </>
            ) : (
              "Sign In"
            )}
          </button>
        </div>
      </div>
    </div>
  );
}