import React, { useEffect, useMemo, useState } from "react";
import {
  Bot,
  Check,
  MessageCircle,
  Save,
  Sparkles,
  Type,
  Move,
  Wand2,
} from "lucide-react";
import "../Style.css";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || window.location.origin;

function getToken() {
  return localStorage.getItem("auth_token") || localStorage.getItem("token") || "";
}

const THEMES = [
  { name: "Default", key: "default", primary: "#6366f1", secondary: "#eef2ff", background: "#ffffff" },
  { name: "Ocean Blue", key: "ocean", primary: "#0ea5e9", secondary: "#e0f2fe", background: "#ffffff" },
  { name: "Emerald", key: "emerald", primary: "#10b981", secondary: "#d1fae5", background: "#ffffff" },
  { name: "Sunset", key: "sunset", primary: "#f59e0b", secondary: "#fef3c7", background: "#ffffff" },
  { name: "Rose", key: "rose", primary: "#f43f5e", secondary: "#ffe4e6", background: "#ffffff" },
  { name: "Dark Mode", key: "dark", primary: "#8b5cf6", secondary: "#1e293b", background: "#0f172a" },
  { name: "Minimal", key: "minimal", primary: "#475569", secondary: "#f1f5f9", background: "#ffffff" },
  { name: "Brand Purple", key: "purple", primary: "#7c3aed", secondary: "#ede9fe", background: "#ffffff" },
  { name: "Coral", key: "coral", primary: "#f87171", secondary: "#fee2e2", background: "#ffffff" },
  { name: "Teal", key: "teal", primary: "#14b8a6", secondary: "#ccfbf1", background: "#ffffff" },
  { name: "Midnight", key: "midnight", primary: "#4f46e5", secondary: "#1e293b", background: "#0f172a" },
  { name: "Lavender", key: "lavender", primary: "#a78bfa", secondary: "#f3e8ff", background: "#ffffff" },
];

const EFFECTS = ["none", "pulse", "bounce", "wiggle", "glow", "heartbeat"];

function getInitialAgentType() {
  const params = new URLSearchParams(window.location.search || "");
  const fromUrl = params.get("agent_type");
  if (fromUrl === "product") return "product";
  if (fromUrl === "chat") return "chat";
  return localStorage.getItem("selected_agent_type") === "product"
    ? "product"
    : "chat";
}

function getInitialAgentId() {
  const params = new URLSearchParams(window.location.search || "");
  return params.get("agent_id") || localStorage.getItem("selected_product_agent_id") || "";
}

export default function CustomizeBotPage() {
  const [agentType, setAgentType] = useState(getInitialAgentType());
  const [selectedAgentId, setSelectedAgentId] = useState(getInitialAgentId());
  const [productAgents, setProductAgents] = useState([]);

  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [status, setStatus] = useState({ type: "", message: "" });

  const [settings, setSettings] = useState({
    theme_name: "rose",
    theme_config: {
      primary_color: "#f43f5e",
      secondary_color: "#ffe4e6",
      background_color: "#ffffff",
      text_color: "#0f172a",
    },
    widget_config: {
      font_family: "System Default",
      widget_position: "bottom_right",
      offset_horizontal: 20,
      offset_vertical: 20,
      button_effect: "none",
    },
    behavior_config: {
      show_handoff_cta: true,
      show_online_badge: true,
    },
  });

  const theme = settings.theme_config;
  const widget = settings.widget_config;

  const selectedProductAgent = productAgents.find((item) => String(item.id) === String(selectedAgentId));

  const previewTitle = useMemo(() => {
    if (agentType === "product") return selectedProductAgent?.agent_name || "Product Assistant";
    return "Chat Assistant";
  }, [agentType, selectedProductAgent]);

  useEffect(() => {
    if (agentType === "product") {
      loadProductAgents();
    }
  }, [agentType]);

  useEffect(() => {
    loadSettings(agentType, selectedAgentId);
  }, [agentType, selectedAgentId]);

  const loadProductAgents = async () => {
    const token = getToken();
    if (!token) return;

    try {
      const response = await fetch(`${API_BASE_URL}/api/product-agents`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) throw new Error(data?.detail || "Could not load product agents.");
      const agents = data?.agents || [];
      setProductAgents(agents);

      if (!selectedAgentId && agents.length) {
        const firstId = String(agents[0].id);
        setSelectedAgentId(firstId);
        localStorage.setItem("selected_product_agent_id", firstId);
      }
    } catch (err) {
      setStatus({ type: "error", message: err.message || "Could not load product agents." });
    }
  };

  const loadSettings = async (type, agentId = "") => {
    const token = getToken();
    if (!token) return;

    try {
      setIsLoading(true);
      setStatus({ type: "", message: "" });

      const response = await fetch(
        `${API_BASE_URL}/agent-widget-settings?agent_type=${encodeURIComponent(type)}${type === "product" && agentId ? `&agent_id=${encodeURIComponent(agentId)}` : ""}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const data = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(data?.detail || "Could not load widget settings.");
      }

      if (data?.settings) {
        setSettings((prev) => ({
          ...prev,
          ...data.settings,
          theme_config: {
            ...prev.theme_config,
            ...(data.settings.theme_config || {}),
          },
          widget_config: {
            ...prev.widget_config,
            ...(data.settings.widget_config || {}),
          },
          behavior_config: {
            ...prev.behavior_config,
            ...(data.settings.behavior_config || {}),
          },
        }));
      }
    } catch (err) {
      setStatus({ type: "error", message: err.message || "Could not load widget settings." });
    } finally {
      setIsLoading(false);
    }
  };

  const updateTheme = (key, value) => {
    setSettings((prev) => ({
      ...prev,
      theme_config: {
        ...prev.theme_config,
        [key]: value,
      },
    }));
  };

  const updateWidget = (key, value) => {
    setSettings((prev) => ({
      ...prev,
      widget_config: {
        ...prev.widget_config,
        [key]: value,
      },
    }));
  };

  const updateBehavior = (key, value) => {
    setSettings((prev) => ({
      ...prev,
      behavior_config: {
        ...prev.behavior_config,
        [key]: value,
      },
    }));
  };

  const applyTheme = (themeItem) => {
    setSettings((prev) => ({
      ...prev,
      theme_name: themeItem.key,
      theme_config: {
        ...prev.theme_config,
        primary_color: themeItem.primary,
        secondary_color: themeItem.secondary,
        background_color: themeItem.background,
      },
    }));
  };

  const saveSettings = async () => {
    const token = getToken();
    if (!token) {
      setStatus({ type: "error", message: "Login token missing. Please login again." });
      return;
    }

    try {
      setIsSaving(true);
      setStatus({ type: "", message: "" });

      const response = await fetch(
        `${API_BASE_URL}/agent-widget-settings?agent_type=${encodeURIComponent(agentType)}${agentType === "product" && selectedAgentId ? `&agent_id=${encodeURIComponent(selectedAgentId)}` : ""}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            agent_type: agentType,
            agent_id: agentType === "product" && selectedAgentId ? Number(selectedAgentId) : null,
            theme_name: settings.theme_name,
            theme_config: settings.theme_config,
            widget_config: settings.widget_config,
            behavior_config: settings.behavior_config,
          }),
        }
      );

      const data = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(data?.detail || "Could not save widget appearance.");
      }

      if (data?.settings) {
        setSettings((prev) => ({
          ...prev,
          ...data.settings,
        }));
      }

      setStatus({ type: "success", message: data?.message || "Widget appearance saved successfully." });
    } catch (err) {
      setStatus({ type: "error", message: err.message || "Could not save widget appearance." });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f6f8fc]">
      <div className="border-b border-slate-200 bg-white px-6 py-5">
        <div className="mx-auto flex max-w-7xl items-center justify-between">
          <div>
            <h1 className="text-xl font-extrabold text-slate-900">
              Customize Bot
            </h1>
            <p className="text-sm text-slate-500">
              Customize public chat widget appearance for each agent.
            </p>
          </div>

          <div className="flex items-center gap-3">
            <select
              value={agentType}
              onChange={(e) => {
                const value = e.target.value;
                setAgentType(value);
                localStorage.setItem("selected_agent_type", value);
              }}
              className="h-11 rounded-xl border border-slate-200 bg-white px-4 text-sm font-bold text-slate-700 outline-none"
            >
              <option value="chat">Chat Agent</option>
              <option value="product">Product Agent</option>
            </select>

            {agentType === "product" && (
              <select
                value={selectedAgentId}
                onChange={(e) => {
                  const value = e.target.value;
                  setSelectedAgentId(value);
                  localStorage.setItem("selected_product_agent_id", value);
                }}
                className="h-11 rounded-xl border border-slate-200 bg-white px-4 text-sm font-bold text-slate-700 outline-none"
              >
                <option value="">Select Product Bot</option>
                {productAgents.map((agent) => (
                  <option key={agent.id} value={agent.id}>
                    {agent.agent_name}
                  </option>
                ))}
              </select>
            )}

            <button
              onClick={saveSettings}
              disabled={isSaving || isLoading}
              className="inline-flex h-11 items-center gap-2 rounded-xl bg-purple-600 px-5 text-sm font-bold text-white shadow-sm hover:bg-purple-700 disabled:cursor-not-allowed disabled:opacity-60"
            >
              <Save className="h-4 w-4" />
              {isSaving ? "Saving..." : "Save Widget Appearance"}
            </button>
          </div>
        </div>
      </div>

      <main className="mx-auto grid max-w-7xl gap-6 px-6 py-7 lg:grid-cols-[1fr_380px]">
        {status.message && (
          <div
            className={`lg:col-span-2 rounded-2xl border px-5 py-4 text-sm font-bold ${
              status.type === "error"
                ? "border-red-200 bg-red-50 text-red-700"
                : "border-emerald-200 bg-emerald-50 text-emerald-700"
            }`}
          >
            {status.message}
          </div>
        )}
        <section className="space-y-6">
          <Card
            icon={<Sparkles className="h-5 w-5 text-purple-600" />}
            title="Color Themes"
            subtitle="Pick a preset or fine-tune with custom colors below"
          >
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {THEMES.map((item) => (
                <button
                  key={item.key}
                  type="button"
                  onClick={() => applyTheme(item)}
                  className={`relative rounded-2xl border bg-white p-3 text-left transition hover:shadow-md ${
                    settings.theme_name === item.key
                      ? "border-purple-500 ring-2 ring-purple-100"
                      : "border-slate-200"
                  }`}
                >
                  {settings.theme_name === item.key && (
                    <span className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full bg-purple-600 text-white">
                      <Check className="h-4 w-4" />
                    </span>
                  )}

                  <div className="rounded-xl border border-slate-100 bg-slate-50 p-2">
                    <div
                      className="h-7 rounded-t-lg"
                      style={{ background: item.primary }}
                    />
                    <div className="space-y-2 rounded-b-lg bg-white p-2">
                      <div
                        className="h-3 w-20 rounded-full"
                        style={{ background: item.secondary }}
                      />
                      <div
                        className="ml-auto h-3 w-16 rounded-full"
                        style={{ background: item.primary }}
                      />
                    </div>
                  </div>

                  <p className="mt-3 text-center text-xs font-extrabold text-slate-600">
                    {item.name}
                  </p>
                </button>
              ))}
            </div>

            <div className="mt-6 border-t border-slate-100 pt-5">
              <p className="mb-4 text-xs font-extrabold uppercase tracking-wider text-slate-500">
                Custom Colors
              </p>

              <div className="grid gap-4 md:grid-cols-3">
                <ColorInput
                  label="Primary"
                  value={theme.primary_color}
                  onChange={(v) => updateTheme("primary_color", v)}
                />
                <ColorInput
                  label="Secondary"
                  value={theme.secondary_color}
                  onChange={(v) => updateTheme("secondary_color", v)}
                />
                <ColorInput
                  label="Background"
                  value={theme.background_color}
                  onChange={(v) => updateTheme("background_color", v)}
                />
              </div>
            </div>
          </Card>

          <Card
            icon={<Type className="h-5 w-5 text-purple-600" />}
            title="Widget Font"
            subtitle="Google fonts can be loaded later in the widget"
          >
            <select
              value={widget.font_family}
              onChange={(e) => updateWidget("font_family", e.target.value)}
              className="h-12 w-full rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-700 outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
            >
              <option>System Default</option>
              <option>Inter</option>
              <option>Poppins</option>
              <option>Roboto</option>
              <option>Nunito</option>
            </select>
          </Card>

          <Card
            icon={<Move className="h-5 w-5 text-purple-600" />}
            title="Widget Position"
            subtitle="Control where your public chat widget appears"
          >
            <div className="flex flex-wrap gap-3">
              <ChoiceButton
                active={widget.widget_position === "bottom_left"}
                onClick={() => updateWidget("widget_position", "bottom_left")}
              >
                Bottom Left
              </ChoiceButton>
              <ChoiceButton
                active={widget.widget_position === "bottom_right"}
                onClick={() => updateWidget("widget_position", "bottom_right")}
              >
                Bottom Right
              </ChoiceButton>
            </div>

            <div className="mt-6 grid gap-5 md:grid-cols-2">
              <Slider
                label="Horizontal"
                value={widget.offset_horizontal}
                onChange={(v) => updateWidget("offset_horizontal", Number(v))}
              />
              <Slider
                label="Vertical"
                value={widget.offset_vertical}
                onChange={(v) => updateWidget("offset_vertical", Number(v))}
              />
            </div>
          </Card>

          <Card
            icon={<Wand2 className="h-5 w-5 text-purple-600" />}
            title="Button Effect"
            subtitle="Add an eye-catching animation to your floating chat button"
          >
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-6">
              {EFFECTS.map((effect) => (
                <button
                  key={effect}
                  type="button"
                  onClick={() => updateWidget("button_effect", effect)}
                  className={`rounded-2xl border bg-white p-4 text-center transition hover:shadow-md ${
                    widget.button_effect === effect
                      ? "border-purple-500 ring-2 ring-purple-100"
                      : "border-slate-200"
                  }`}
                >
                  <div
                    className="mx-auto flex h-10 w-10 items-center justify-center rounded-full text-white"
                    style={{ background: theme.primary_color }}
                  >
                    <MessageCircle className="h-5 w-5" />
                  </div>
                  <p className="mt-3 text-xs font-extrabold capitalize text-slate-700">
                    {effect}
                  </p>
                </button>
              ))}
            </div>
          </Card>

          <Card
            icon={<Bot className="h-5 w-5 text-purple-600" />}
            title="Widget Behavior"
            subtitle="Control visitor-facing buttons and extra widget behavior"
          >
            <Toggle
              label="Show handoff CTA"
              checked={settings.behavior_config.show_handoff_cta}
              onChange={(v) => updateBehavior("show_handoff_cta", v)}
            />
            <Toggle
              label="Show online badge"
              checked={settings.behavior_config.show_online_badge}
              onChange={(v) => updateBehavior("show_online_badge", v)}
            />
          </Card>
        </section>

        <aside className="lg:sticky lg:top-6 lg:self-start">
          <p className="mb-3 text-xs font-extrabold uppercase tracking-wider text-slate-400">
            Live Preview
          </p>

          <div className="rounded-3xl border border-slate-200 bg-white p-4 shadow-sm">
            <div
              className="overflow-hidden rounded-2xl border border-slate-200"
              style={{
                background: theme.background_color,
                fontFamily:
                  widget.font_family === "System Default"
                    ? "inherit"
                    : widget.font_family,
              }}
            >
              <div
                className="px-4 py-4 text-white"
                style={{ background: theme.primary_color }}
              >
                <div className="flex items-center gap-3">
                  <div className="flex h-9 w-9 items-center justify-center rounded-full bg-white/20">
                    <Bot className="h-5 w-5" />
                  </div>
                  <div>
                    <p className="text-sm font-extrabold">{previewTitle}</p>
                    {settings.behavior_config.show_online_badge && (
                      <p className="text-xs opacity-80">Online</p>
                    )}
                  </div>
                </div>
              </div>

              <div className="space-y-3 p-4">
                <Bubble color={theme.secondary_color}>
                  Welcome! How can I help you today?
                </Bubble>

                <Bubble user color={theme.primary_color}>
                  I want to know about products
                </Bubble>

                <Bubble color={theme.secondary_color}>
                  Sure, I can help you with that.
                </Bubble>

                <div className="rounded-xl border border-slate-200 bg-white p-3">
                  <div
                    className="h-16 rounded-lg"
                    style={{ background: theme.secondary_color }}
                  />
                  <p className="mt-3 text-xs font-extrabold text-slate-700">
                    Product / Service Card
                  </p>
                  <button
                    className="mt-2 rounded-full px-3 py-1 text-xs font-bold text-white"
                    style={{ background: theme.primary_color }}
                  >
                    View
                  </button>
                </div>
              </div>

              {settings.behavior_config.show_handoff_cta && (
                <div className="border-t border-slate-100 py-2 text-center text-xs font-semibold text-slate-400 underline">
                  Talk to a human
                </div>
              )}

              <div className="flex items-center gap-2 border-t border-slate-100 p-3">
                <input
                  disabled
                  placeholder="Type your message..."
                  className="h-10 flex-1 rounded-xl border-0 px-3 text-xs outline-none"
                  style={{ background: theme.secondary_color }}
                />
                <button
                  className="flex h-10 w-10 items-center justify-center rounded-xl text-white"
                  style={{ background: theme.primary_color }}
                >
                  <MessageCircle className="h-4 w-4" />
                </button>
              </div>
            </div>

            <div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-4 text-xs text-slate-400">
              <span>
                Offset: {widget.offset_horizontal}px × {widget.offset_vertical}px
              </span>
              <span>
                Position:{" "}
                {widget.widget_position === "bottom_right"
                  ? "Bottom Right"
                  : "Bottom Left"}
              </span>
            </div>

            <div className="mt-4 flex items-center gap-3">
              <div
                className={`flex h-14 w-14 items-center justify-center rounded-full text-white shadow-lg ${
                  widget.button_effect === "pulse" ? "animate-pulse" : ""
                }`}
                style={{ background: theme.primary_color }}
              >
                <MessageCircle className="h-6 w-6" />
              </div>
              <div className="text-xs text-slate-400">
                Floating button: {widget.button_effect}
                <br />
                Font: {widget.font_family}
              </div>
            </div>
          </div>
        </aside>
      </main>
    </div>
  );
}

function Card({ icon, title, subtitle, children }) {
  return (
    <div className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
      <div className="mb-5 flex items-start gap-3">
        <div className="mt-0.5">{icon}</div>
        <div>
          <h2 className="text-base font-extrabold text-slate-900">{title}</h2>
          {subtitle && <p className="text-sm text-slate-500">{subtitle}</p>}
        </div>
      </div>
      {children}
    </div>
  );
}

function ColorInput({ label, value, onChange }) {
  return (
    <label>
      <span className="mb-2 block text-xs font-bold text-slate-500">
        {label}
      </span>
      <div className="flex h-12 items-center gap-2 rounded-xl border border-slate-200 bg-white px-2">
        <input
          type="color"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="h-8 w-9 cursor-pointer rounded border-0 bg-transparent"
        />
        <input
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="flex-1 text-sm font-semibold text-slate-700 outline-none"
        />
      </div>
    </label>
  );
}

function ChoiceButton({ active, children, onClick }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`h-11 rounded-xl border px-5 text-sm font-bold transition ${
        active
          ? "border-purple-500 bg-purple-50 text-purple-700"
          : "border-slate-200 bg-white text-slate-600"
      }`}
    >
      {children}
    </button>
  );
}

function Slider({ label, value, onChange }) {
  return (
    <label>
      <div className="mb-2 flex items-center justify-between">
        <span className="text-xs font-bold text-slate-500">{label}</span>
        <span className="rounded-md bg-slate-50 px-2 py-1 text-xs font-bold text-slate-400">
          {value}px
        </span>
      </div>
      <input
        type="range"
        min="0"
        max="80"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full"
      />
    </label>
  );
}

function Toggle({ label, checked, onChange }) {
  return (
    <label className="flex items-center justify-between rounded-2xl border border-slate-100 px-4 py-3">
      <span className="text-sm font-bold text-slate-700">{label}</span>
      <input
        type="checkbox"
        checked={checked}
        onChange={(e) => onChange(e.target.checked)}
      />
    </label>
  );
}

function Bubble({ children, user = false, color }) {
  return (
    <div
      className={`max-w-[78%] rounded-2xl px-3 py-2 text-xs leading-5 ${
        user ? "ml-auto text-white" : "text-slate-700"
      }`}
      style={{ background: color }}
    >
      {children}
    </div>
  );
}