import React, { useState } from "react";

const DEFAULT_FORM = {
  title: "",
  page_type: "manual_entry",
  priority: 50,
  url: "",
  tags: "",
  images: "",
  links: "",
  text: "",
  active: true,
};

function textToList(value) {
  return String(value || "")
    .split(/\n|,/)
    .map((item) => item.trim())
    .filter(Boolean);
}

export default function AddKnowledgeEntryModal({ open, onClose, onSubmit }) {
  const [form, setForm] = useState(DEFAULT_FORM);
  const [error, setError] = useState("");

  if (!open) return null;

  function updateField(name, value) {
    setForm((prev) => ({ ...prev, [name]: value }));
  }

  function handleClose() {
    setError("");
    setForm(DEFAULT_FORM);
    onClose();
  }

  function handleSubmit(e) {
    e.preventDefault();
    setError("");

    if (!form.title.trim()) {
      setError("Title is required.");
      return;
    }

    if (!form.text.trim()) {
      setError("Knowledge text is required.");
      return;
    }

    const payload = {
      title: form.title.trim(),
      page_type: form.page_type.trim() || "manual_entry",
      priority: Number(form.priority || 0),
      url: form.url.trim(),
      tags: textToList(form.tags),
      images: textToList(form.images),
      links: textToList(form.links),
      text: form.text.trim(),
      is_disabled: !form.active,
      
    };

    onSubmit(payload);
    setForm(DEFAULT_FORM);
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4">
      <div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-3xl bg-white p-6 shadow-2xl">
        <div className="mb-5 flex items-start justify-between gap-4">
          <div>
            <h2 className="text-xl font-bold text-slate-900">Add Knowledge Entry</h2>
            <p className="mt-1 text-sm text-slate-500">
              Add manual knowledge that will later be trained into this tenant&apos;s AI brain.
            </p>
          </div>
          <button
            type="button"
            onClick={handleClose}
            className="rounded-full px-3 py-1 text-xl leading-none text-slate-400 hover:bg-slate-100 hover:text-slate-700"
            aria-label="Close"
          >
            ×
          </button>
        </div>

        {error && <div className="mb-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</div>}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-sm font-semibold text-slate-700">Title</label>
            <input
              value={form.title}
              onChange={(e) => updateField("title", e.target.value)}
              className="w-full rounded-xl border border-slate-200 px-4 py-2 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
              placeholder="e.g. Return Policy"
            />
          </div>

          <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
            <div>
              <label className="mb-1 block text-sm font-semibold text-slate-700">Page Type</label>
              <input
                value={form.page_type}
                onChange={(e) => updateField("page_type", e.target.value)}
                className="w-full rounded-xl border border-slate-200 px-4 py-2 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
                placeholder="manual_entry / product_page / company_page"
              />
            </div>
            <div>
              <label className="mb-1 block text-sm font-semibold text-slate-700">Priority</label>
              <input
                type="number"
                value={form.priority}
                onChange={(e) => updateField("priority", e.target.value)}
                className="w-full rounded-xl border border-slate-200 px-4 py-2 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
                placeholder="50"
              />
            </div>
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-slate-700">Source URL</label>
            <input
              value={form.url}
              onChange={(e) => updateField("url", e.target.value)}
              className="w-full rounded-xl border border-slate-200 px-4 py-2 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
              placeholder="https://example.com/page"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-slate-700">Exact Knowledge Text</label>
            <textarea
              value={form.text}
              onChange={(e) => updateField("text", e.target.value)}
              className="h-40 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
              placeholder="Write the information your AI agent should know..."
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-slate-700">Tags</label>
            <input
              value={form.tags}
              onChange={(e) => updateField("tags", e.target.value)}
              className="w-full rounded-xl border border-slate-200 px-4 py-2 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
              placeholder="returns, shipping, faq"
            />
            <p className="mt-1 text-xs text-slate-400">Use comma-separated tags.</p>
          </div>

          <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
            <div>
              <label className="mb-1 block text-sm font-semibold text-slate-700">Images</label>
              <textarea
                value={form.images}
                onChange={(e) => updateField("images", e.target.value)}
                className="h-24 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
                placeholder="Image URLs, one per line"
              />
            </div>
            <div>
              <label className="mb-1 block text-sm font-semibold text-slate-700">Important Links</label>
              <textarea
                value={form.links}
                onChange={(e) => updateField("links", e.target.value)}
                className="h-24 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
                placeholder="Important links, one per line"
              />
            </div>
          </div>

          <label className="flex items-center gap-3 rounded-xl border border-slate-200 p-3 text-sm text-slate-700">
            <input
              type="checkbox"
              checked={form.active}
              onChange={(e) => updateField("active", e.target.checked)}
              className="h-4 w-4 accent-purple-600"
            />
            <span><strong>Active</strong> — the AI agent will use this entry</span>
          </label>

          <div className="flex justify-end gap-3 border-t border-slate-100 pt-4">
            <button
              type="button"
              onClick={handleClose}
              className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="rounded-xl bg-purple-600 px-4 py-2 text-sm font-semibold text-white shadow-sm hover:opacity-90"
            >
              Add Entry
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
