import React from "react";
import { Briefcase, CreditCard, Grid3X3, LogOut, MessageSquare, Phone, Settings, Users } from "lucide-react";

const navItems = [
  { label: "Overview", icon: Grid3X3, path: "/dashboard" },
  { label: "Chat Agents", icon: MessageSquare, path: "/customize-bot" },
  { label: "Contacts", icon: Users, path: "/contacts" },
  { label: "Knowledge Base", icon: Briefcase, path: "/knowledge-base" },
];

const exploreItems = [
  { label: "Voice Agents", icon: Phone, path: "#" },
  { label: "Integration", icon: Settings, path: "/integration" },
  { label: "Product Bot", icon: MessageSquare, path: "/product-agents" },
];

const accountItems = [
  { label: "Team", icon: Users, path: "#" },
  { label: "Billing", icon: CreditCard, path: "#" },
  { label: "Settings", icon: Settings, path: "#" },
];

function getUserName() {
  return localStorage.getItem("tenant_name") || localStorage.getItem("user_name") || "Your Business";
}

function NavLink({ item, active }) {
  const Icon = item.icon;
  return (
    <button
      type="button"
      onClick={() => {
        if (item.path && item.path !== "#") window.location.href = item.path;
      }}
      className={`flex w-full items-center gap-3 rounded-lg px-4 py-3 text-left text-[14px] font-medium transition ${
        active ? "bg-[var(--primary-color)] text-white" : "text-slate-400 hover:bg-white/5 hover:text-white"
      }`}
    >
      <Icon className="h-5 w-5" />
      <span>{item.label}</span>
    </button>
  );
}

function Section({ title, items, activePath }) {
 const setupPaths = [
  "/train",
  "/step2",
  "/review-agent",
  "/customize-bot",
  "/step3",
  "/product-public-url",
  "/product-chat",
  "/product-agents",
];
  return (
    <div className="mt-7">
      <p className="mb-3 px-4 text-[11px] font-bold uppercase tracking-[0.16em] text-slate-500">{title}</p>
      <div className="space-y-1">
        {items.map((item) => (
          <NavLink
            key={item.label}
            item={item}
            active={
            activePath === item.path ||
            (item.path === "/customize-bot" && setupPaths.includes(activePath)) ||
            (item.path === "/product-agents" && activePath === "/product-agents")
          }
          />
        ))}
      </div>
    </div>
  );
}

export default function Sidebar() {
  const activePath = window.location.pathname;
  const userName = getUserName();
  const initials = userName
    .split(" ")
    .map((word) => word[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  const logout = () => {
    localStorage.removeItem("auth_token");
    localStorage.removeItem("tenant_slug");
    localStorage.removeItem("tenant_id");
    localStorage.removeItem("user_email");
    localStorage.removeItem("user_name");
    localStorage.removeItem("tenant_name");
    localStorage.removeItem("active_training_job_id");
    localStorage.removeItem("last_training_url");
    window.location.href = "/";
  };

  return (
    <aside className="fixed inset-y-0 left-0 z-30 hidden w-[260px] flex-col bg-[#0f172a] text-white lg:flex overflow-y-auto">
      <div className="flex h-[72px] items-center gap-3 px-5">
        <img
          src="/sandlus-logo.png"
          alt="Sandlus Logo"
          className="h-11 w-auto object-contain"
          onError={(e) => {
            e.currentTarget.style.display = "none";
          }}
        />
        <div className="text-[20px] font-extrabold tracking-tight">SAND BOT</div>
      </div>

      <nav className="flex-1 px-3 pt-2">
        <Section title="Workspace" items={navItems} activePath={activePath} />
        <Section title="Explore More" items={exploreItems} activePath={activePath} />
        <Section title="Account" items={accountItems} activePath={activePath} />
      </nav>

      <div className="border-t border-white/10 p-5">
        <div className="flex items-center justify-between">
          <div className="flex min-w-0 items-center gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-purple-600 text-sm font-bold">
              {initials || "YK"}
            </div>
            <div className="min-w-0">
              <p className="truncate text-sm font-semibold text-white">{userName}</p>
              <p className="text-xs text-slate-500">Member</p>
            </div>
          </div>
          <button type="button" onClick={logout} className="rounded-lg p-2 text-slate-500 hover:bg-white/5 hover:text-white" title="Logout">
            <LogOut className="h-5 w-5" />
          </button>
        </div>
      </div>
    </aside>
  );
}

