import React, { useState } from "react";
import "./Style.css";
import { Bot, MessageSquare, Plus, Sparkles } from "lucide-react";
import AgentSteps from "./training/AgentSteps";

const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL || "http://localhost:8000";

export default function AgentTypePage() {
  const initialType =
    localStorage.getItem("active_agent_type") ||
    localStorage.getItem("selected_agent_type") ||
    "chat";

  const [selected, setSelected] = useState(
    initialType === "product" ? "product" : "chat"
  );
  const [saving, setSaving] = useState(false);

  const chooseAgent = (type) => {
    const agentType = type === "product" ? "product" : "chat";

    setSelected(agentType);
    localStorage.setItem("selected_agent_type", agentType);
  };

  const saveActiveAgentTypeToDB = async (agentType) => {
    const token = localStorage.getItem("auth_token");

    if (!token) {
      throw new Error("Login token missing. Please login again.");
    }

    const res = await fetch(`${API_BASE_URL}/tenant/active-agent-type`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
      
        active_agent_type: agentType,
      }),
    });

    const data = await res.json().catch(() => null);

    if (!res.ok) {
      throw new Error(data?.detail || "Could not save active agent type.");
    }

    return data;
  };

  const continueFlow = async () => {
    try {
      setSaving(true);

      localStorage.setItem("selected_agent_type", selected);

      if (selected === "product") {
        const params = new URLSearchParams(window.location.search || "");
        const agentId = params.get("agent_id") || localStorage.getItem("selected_product_agent_id") || "";
        window.location.href = agentId
          ? `/integration?agent_type=product&agent_id=${agentId}`
          : "/integration?agent_type=product";
        return;
      }

      localStorage.setItem("active_agent_type", selected);
      localStorage.setItem("public_chat_agent_type", selected);
      await saveActiveAgentTypeToDB(selected);
      window.location.href = "/train";
    } catch (err) {
      alert(err.message || "Could not save agent type.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="min-h-[calc(100vh-72px)] bg-[#f6f8fc]">
      <div className="border-b border-slate-100 bg-white px-6 py-5 lg:px-8">
        <div className="flex items-center justify-between">
          <button className="inline-flex items-center gap-3 text-[16px] font-bold text-slate-900">
            <Plus className="h-5 w-5 text-purple-600" /> Create New Agent
          </button>
          <p className="text-xs font-semibold text-slate-400">Step 1 of 5</p>
        </div>
      </div>

      <AgentSteps current={1} />

      <main className="px-4 py-8 sm:px-6">
        <section className="mx-auto max-w-6xl rounded-sm bg-white shadow-sm">
          <div className="mx-auto max-w-4xl px-5 py-8 text-center">
            <div className="mx-auto mb-5 flex h-20 w-20 items-center justify-center rounded-3xl bg-purple-100">
              <Sparkles className="h-10 w-10 text-purple-600" />
            </div>
            <h2 className="text-[32px] font-extrabold tracking-tight text-slate-950">
              Create your AI agent
            </h2>
            <p className="mx-auto mt-3 max-w-xl text-[17px] leading-7 text-slate-500">
              Choose what type of agent you want to create. This will start your tenant training flow.
            </p>
          </div>

          <div className="mx-auto mt-10 grid max-w-4xl gap-5 md:grid-cols-2">
            <button
              type="button"
              onClick={() => chooseAgent("chat")}
              className={`rounded-3xl border-2 bg-white p-7 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md ${
                selected === "chat" ? "border-purple-500" : "border-slate-200"
              }`}
            >
              <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-purple-100 text-purple-600">
                <MessageSquare className="h-7 w-7" />
              </div>
              <h3 className="mt-6 text-xl font-extrabold text-slate-950">
                Chat Agent
              </h3>
              <p className="mt-2 text-sm leading-6 text-slate-500">
                Train your website/document based chatbot for web and WhatsApp conversations.
              </p>
            </button>

            <button
              type="button"
              onClick={() => chooseAgent("product")}
              className={`rounded-3xl border-2 bg-white p-7 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md ${
                selected === "product" ? "border-purple-500" : "border-slate-200"
              }`}
            >
              <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-slate-100 text-slate-500">
                <Bot className="h-7 w-7" />
              </div>
              <h3 className="mt-6 text-xl font-extrabold text-slate-950">
                Product Agent
              </h3>
              <p className="mt-2 text-sm leading-6 text-slate-500">
                Search products from your connected tenant database.
              </p>
            </button>
          </div>

          <div className="mx-auto mt-14 flex max-w-4xl items-center justify-between pb-10">
            <button
              type="button"
              onClick={() => window.history.back()}
              className="rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-bold text-slate-600 shadow-sm"
            >
              ← Back
            </button>

            <button
              type="button"
              onClick={continueFlow}
              disabled={saving}
              className="rounded-xl bg-purple-500 px-6 py-3 text-sm font-bold text-white shadow-sm hover:bg-[var(--btn-hover-color)] disabled:cursor-not-allowed disabled:opacity-60"
            >
              {saving ? "Saving..." : "Continue →"}
            </button>
          </div>
        </section>
      </main>
    </div>
  );
}