import React, { useEffect, useState } from "react";
import {
  Bot,
  CheckCircle2,
  Database,
  Edit3,
  ExternalLink,
  Loader2,
  Palette,
  Plus,
  Settings,
  ToggleLeft,
  ToggleRight,
  Trash2,
} from "lucide-react";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || window.location.origin;

function getToken() {
  return localStorage.getItem("auth_token") || localStorage.getItem("token") || "";
}

function authHeaders() {
  return { Authorization: `Bearer ${getToken()}` };
}

export default function ProductAgentsPage() {
  const [loading, setLoading] = useState(true);
  const [savingId, setSavingId] = useState(null);
  const [error, setError] = useState("");
  const [agents, setAgents] = useState([]);

  useEffect(() => {
    loadProductAgents();
  }, []);

  const loadProductAgents = async () => {
    const token = getToken();
    if (!token) {
      setError("Login token missing. Please login again.");
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError("");
      const res = await fetch(`${API_BASE_URL}/api/product-agents`, {
        headers: authHeaders(),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data?.detail || "Could not load product agents.");
      setAgents(data?.agents || []);
    } catch (err) {
      setError(err.message || "Could not load product agents.");
    } finally {
      setLoading(false);
    }
  };

  const createProductAgent = async () => {
    const name = window.prompt("Enter product bot name", "Product Bot");
    if (name === null) return;

    try {
      setSavingId("create");
      setError("");
      const res = await fetch(`${API_BASE_URL}/product-agents`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...authHeaders(),
        },
        body: JSON.stringify({ agent_name: name || "Product Bot" }),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data?.detail || "Could not create product agent.");
      const agentId = data?.agent?.id;
      localStorage.setItem("selected_agent_type", "product");
      if (agentId) localStorage.setItem("selected_product_agent_id", String(agentId));
      window.location.href = agentId
        ? `/agent-type?create=product&agent_id=${agentId}`
        : "/agent-type?create=product";
    } catch (err) {
      setError(err.message || "Could not create product agent.");
      setSavingId(null);
    }
  };

  const updateStatus = async (agent, status) => {
    try {
      setSavingId(agent.id);
      setError("");
      const res = await fetch(`${API_BASE_URL}/api/product-agents/${agent.id}/status`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          ...authHeaders(),
        },
        body: JSON.stringify({ status }),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data?.detail || "Could not update agent status.");
      setAgents((prev) => prev.map((item) => (item.id === agent.id ? data.agent : item)));
    } catch (err) {
      setError(err.message || "Could not update agent status.");
    } finally {
      setSavingId(null);
    }
  };

  const renameAgent = async (agent) => {
    const name = window.prompt("Edit product bot name", agent.agent_name || "Product Bot");
    if (name === null) return;
    if (!name.trim()) {
      setError("Agent name cannot be empty.");
      return;
    }

    try {
      setSavingId(agent.id);
      setError("");
      const res = await fetch(`${API_BASE_URL}/api/product-agents/${agent.id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          ...authHeaders(),
        },
        body: JSON.stringify({ agent_name: name.trim() }),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data?.detail || "Could not rename agent.");
      setAgents((prev) => prev.map((item) => (item.id === agent.id ? data.agent : item)));
    } catch (err) {
      setError(err.message || "Could not rename agent.");
    } finally {
      setSavingId(null);
    }
  };

  const deleteAgent = async (agent) => {
    if (!window.confirm(`Delete ${agent.agent_name}?`)) return;
    try {
      setSavingId(agent.id);
      setError("");
      const res = await fetch(`${API_BASE_URL}/api/product-agents/${agent.id}`, {
        method: "DELETE",
        headers: authHeaders(),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) throw new Error(data?.detail || "Could not delete agent.");
      setAgents((prev) => prev.filter((item) => item.id !== agent.id));
    } catch (err) {
      setError(err.message || "Could not delete agent.");
    } finally {
      setSavingId(null);
    }
  };

  const goPipeline = (agent) => {
    localStorage.setItem("selected_agent_type", "product");
    localStorage.setItem("selected_product_agent_id", String(agent.id));
    window.location.href = `/integration?agent_type=product&agent_id=${agent.id}`;
  };

  const goCustomize = (agent) => {
    localStorage.setItem("selected_agent_type", "product");
    localStorage.setItem("selected_product_agent_id", String(agent.id));
    window.location.href = `/customize-bot?agent_type=product&agent_id=${agent.id}`;
  };

  const copyUrl = (agent) => {
    const slug = agent.public_slug || agent.tenant_slug;
    const url = slug ? `${window.location.origin}/product-chat_${slug}` : window.location.origin;
    navigator.clipboard.writeText(url);
  };

  return (
    <div style={{ minHeight: "calc(100vh - 72px)", background: "#f6f8fc", padding: "32px 36px", color: "#0f172a", opacity: 1, filter: "none" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "20px", marginBottom: "28px" }}>
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <h1 style={{ fontSize: "28px", fontWeight: 800, color: "#0f172a", margin: 0 }}>Product Bots</h1>
            <span style={{ borderRadius: "999px", background: "#eef2ff", color: "#475569", padding: "5px 12px", fontSize: "13px", fontWeight: 800 }}>{agents.length}</span>
          </div>
          <p style={{ marginTop: "8px", fontSize: "14px", color: "#64748b" }}>
            Manage product agents, active status, pipeline setup, and individual customization.
          </p>
        </div>

        <button type="button" onClick={createProductAgent} disabled={savingId === "create"} style={{ display: "inline-flex", alignItems: "center", gap: "8px", background: "#ff5a3d", color: "#fff", border: "none", borderRadius: "12px", padding: "14px 22px", fontWeight: 800, cursor: "pointer", opacity: savingId === "create" ? 0.7 : 1 }}>
          {savingId === "create" ? <Loader2 size={16} className="animate-spin" /> : <Plus size={16} />} Create Product Agent
        </button>
      </div>

      {error && (
        <div style={{ marginBottom: "20px", border: "1px solid #fecaca", background: "#fef2f2", color: "#b91c1c", borderRadius: "14px", padding: "14px 16px", fontWeight: 700, fontSize: "14px" }}>
          {error}
        </div>
      )}

      {loading ? (
        <div style={{ height: "260px", background: "#fff", border: "1px solid #e2e8f0", borderRadius: "18px", display: "flex", alignItems: "center", justifyContent: "center", gap: "10px", color: "#64748b", fontWeight: 800 }}>
          <Loader2 size={22} className="animate-spin" /> Loading product bots...
        </div>
      ) : agents.length ? (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(420px, 1fr))", gap: "22px" }}>
          {agents.map((agent) => {
            const isActive = agent.status === "active";
            const isSaving = savingId === agent.id;
            return (
              <div key={agent.id} style={{ background: "#ffffff", border: isActive ? "1px solid #ff5a3d" : "1px solid #e2e8f0", borderRadius: "18px", padding: "24px", boxShadow: "0 8px 24px rgba(15,23,42,0.06)", opacity: 1 }}>
                <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: "16px" }}>
                  <div style={{ display: "flex", alignItems: "flex-start", gap: "14px", minWidth: 0 }}>
                    <div style={{ width: "54px", height: "54px", borderRadius: "16px", background: "#fff0ec", color: "#ff5a3d", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                      <Bot size={28} />
                    </div>
                    <div style={{ minWidth: 0 }}>
                      <h2 style={{ margin: 0, fontSize: "20px", fontWeight: 800, color: "#0f172a", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{agent.agent_name}</h2>
                      <p style={{ margin: "5px 0 0", color: "#64748b", fontSize: "13px", fontWeight: 600 }}>Handler: {agent.handler_key || "product_query_bot"}</p>
                    </div>
                  </div>

                  <button type="button" onClick={() => updateStatus(agent, isActive ? "inactive" : "active")} disabled={isSaving} style={{ display: "inline-flex", alignItems: "center", gap: "7px", border: "none", borderRadius: "999px", padding: "8px 12px", background: isActive ? "#ecfdf5" : "#f1f5f9", color: isActive ? "#047857" : "#64748b", fontSize: "12px", fontWeight: 900, cursor: "pointer" }}>
                    {isSaving ? <Loader2 size={16} className="animate-spin" /> : isActive ? <ToggleRight size={17} /> : <ToggleLeft size={17} />}
                    {isActive ? "ACTIVE" : "INACTIVE"}
                  </button>
                </div>

                <div style={{ marginTop: "18px", display: "flex", flexWrap: "wrap", alignItems: "center", gap: "8px" }}>
                  <span style={{ background: "#fff7ed", color: "#c2410c", borderRadius: "8px", padding: "6px 10px", fontSize: "12px", fontWeight: 800 }}>Product Agent</span>
                  <span style={{ color: "#94a3b8", fontSize: "12px", fontWeight: 700 }}>ID: {agent.id}</span>
                </div>

                <div style={{ marginTop: "18px", display: "grid", gridTemplateColumns: "repeat(3, 1fr)", border: "1px solid #e2e8f0", borderRadius: "14px", overflow: "hidden", background: "#f8fafc" }}>
                  <Metric icon={<Database size={16} />} value="DB" label="Knowledge" />
                  <Metric icon={<CheckCircle2 size={16} />} value={agent.status} label="Status" />
                  <Metric icon={<ExternalLink size={16} />} value="URL" label="Public" />
                </div>

                <div style={{ marginTop: "20px", display: "grid", gridTemplateColumns: "repeat(5, minmax(0, 1fr))", gap: "10px" }}>
                  <ActionButton onClick={() => goPipeline(agent)} icon={<Settings size={16} />} label="Pipeline" />
                  <ActionButton onClick={() => goCustomize(agent)} icon={<Palette size={16} />} label="Customize" highlight />
                  <ActionButton onClick={() => renameAgent(agent)} icon={<Edit3 size={16} />} label="Edit" />
                  <ActionButton onClick={() => copyUrl(agent)} icon={<ExternalLink size={16} />} label="Copy" />
                  <ActionButton onClick={() => deleteAgent(agent)} icon={<Trash2 size={16} />} label="Delete" danger />
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div style={{ background: "#fff", border: "1px dashed #cbd5e1", borderRadius: "18px", padding: "50px", textAlign: "center" }}>
          <Bot size={42} color="#94a3b8" />
          <h2 style={{ marginTop: "16px", fontSize: "21px", fontWeight: 800, color: "#0f172a" }}>No product bot found</h2>
          <p style={{ marginTop: "8px", color: "#64748b" }}>Create a product bot and it will appear here as a manageable card.</p>
          <button onClick={createProductAgent} style={{ marginTop: "20px", background: "#ff5a3d", color: "#fff", border: "none", borderRadius: "12px", padding: "13px 20px", fontWeight: 800, cursor: "pointer" }}>Create Product Agent</button>
        </div>
      )}
    </div>
  );
}

function Metric({ icon, value, label }) {
  return (
    <div style={{ padding: "14px 10px", textAlign: "center", borderRight: "1px solid #e2e8f0" }}>
      <div style={{ display: "flex", justifyContent: "center", color: "#94a3b8", marginBottom: "4px" }}>{icon}</div>
      <div style={{ fontSize: "14px", fontWeight: 900, color: "#0f172a", textTransform: "capitalize" }}>{value}</div>
      <div style={{ marginTop: "3px", fontSize: "10px", fontWeight: 900, letterSpacing: ".06em", color: "#94a3b8", textTransform: "uppercase" }}>{label}</div>
    </div>
  );
}

function ActionButton({ onClick, icon, label, highlight, danger }) {
  return (
    <button onClick={onClick} type="button" style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", gap: "6px", border: highlight ? "1px solid #fed7aa" : danger ? "1px solid #fecaca" : "1px solid #e2e8f0", background: highlight ? "#fff7ed" : danger ? "#fef2f2" : "#fff", color: highlight ? "#c2410c" : danger ? "#b91c1c" : "#334155", borderRadius: "11px", padding: "11px 8px", fontSize: "12px", fontWeight: 900, cursor: "pointer" }}>
      {icon} {label}
    </button>
  );
}
