import React from "react";
import { ChevronDown } from "lucide-react";

function getUserName() {
  return (
    localStorage.getItem("tenant_name") ||
    localStorage.getItem("user_name") ||
    "Your Business"
  );
}

export default function TopNav({ title = "Dashboard" }) {
  const userName = getUserName();
  const initials = userName
    .split(" ")
    .map((word) => word[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  return (
    <header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-slate-200 bg-white px-6 lg:px-8">
      <h1 className="text-[20px] font-bold tracking-tight text-slate-950">{title}</h1>

      <div className="relative group">
        <div className="flex cursor-pointer items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-purple-600 text-sm font-bold text-white">
            {initials || "YK"}
          </div>
          <span className="hidden text-sm font-semibold text-slate-700 sm:inline">{userName}</span>
          <ChevronDown className="h-4 w-4 text-slate-400" />
        </div>

        <div className="absolute right-0 hidden w-40 rounded-xl border border-slate-200 bg-white shadow-lg group-hover:block">
          <button
            className="w-full rounded-lg px-4 py-2 text-left text-sm font-medium text-red-600 hover:bg-red-50"
            onClick={() => {
              localStorage.removeItem("auth_token");
              localStorage.removeItem("user_name");
              localStorage.removeItem("tenant_id");
              localStorage.removeItem("tenant_slug");
              localStorage.removeItem("tenant_name");
              window.location.href = "/";
            }}
          >
            Logout
          </button>
        </div>
      </div>
    </header>
  );
}
