import React, { useEffect, useMemo, useState } from "react";
import {
  AlertCircle,
  BookOpen,
  Bot,
  Clock,
  Copy,
  ExternalLink,
  Loader2,
  MessageSquare,
  Plus,
  Save,
  Shield,
  Sparkles,
  X,
} from "lucide-react";
import AgentSteps from "./training/AgentSteps";

const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL || window.location.origin;

const defaultStarterQuestions = [
  "📞 Connect with Sales Team",
  "🌐 Visit Website",
];

function getToken() {
  return localStorage.getItem("auth_token") || localStorage.getItem("token") || "";
}

function getSelectedAgentType() {
  return localStorage.getItem("selected_agent_type") === "product" ? "product" : "chat";
}

function publicLinkPath() {
  return `/public-link?agent_type=${getSelectedAgentType()}`;
}

