function safeArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === "string") {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  return [];
}
export default function ReviewAgentPage() {
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [config, setConfig] = useState(null);

  const [businessName, setBusinessName] = useState("");
  const [industry, setIndustry] = useState("");
  const [businessType, setBusinessType] = useState("");
  const [businessDescription, setBusinessDescription] = useState("");
  const [websiteUrl, setWebsiteUrl] = useState("");
  const [greetingMessage, setGreetingMessage] = useState("");
  const [starterQuestions, setStarterQuestions] = useState(defaultStarterQuestions);
  const [newQuestion, setNewQuestion] = useState("");
  const [systemPrompt, setSystemPrompt] = useState("");
  const [restrictionRules, setRestrictionRules] = useState("");
  const [allowedScope, setAllowedScope] = useState("");
  const [blockedClaims, setBlockedClaims] = useState("");
  const [openingTime, setOpeningTime] = useState("09:00 AM");
  const [closingTime, setClosingTime] = useState("06:00 PM");
  const [workingDays, setWorkingDays] = useState("Monday - Saturday");

  const [showUrlPopup, setShowUrlPopup] = useState(false);
  const [linkData, setLinkData] = useState(null);
  const [sweetName, setSweetName] = useState("");
  const [urlLoading, setUrlLoading] = useState(false);
  const [urlSaving, setUrlSaving] = useState(false);
  const [copied, setCopied] = useState(false);

  const trainingSummary = config?.training_summary || {};
  const knowledgeBase = config?.knowledge_base || {};

  const processedSources = useMemo(
    () => knowledgeBase.processed_sources || [],
    [knowledgeBase]
  );
  const skippedSources = useMemo(
    () => knowledgeBase.skipped_sources || [],
    [knowledgeBase]
  );
  const failedSources = useMemo(
    () => knowledgeBase.failed_sources || [],
    [knowledgeBase]
  );

  useEffect(() => {
    fetchAgentConfig();
  }, []);

  const hydrateForm = (data) => {
    const cfg = data?.config || {};
    setConfig(cfg);

    setBusinessName(cfg.business?.name || cfg.tenant?.tenant_name || "");
    setIndustry(cfg.business?.industry || "General Business");
    setBusinessType(
      cfg.business?.type || localStorage.getItem("business_type") || "Business"
    );
    setBusinessDescription(cfg.business?.description || "");
    setWebsiteUrl(cfg.business?.website_url || cfg.website_url || "");
    setGreetingMessage(
      cfg.chat_experience?.greeting_message ||
        "Welcome! How can I help you today?"
    );
    setStarterQuestions(safeArray(cfg.chat_experience?.starter_questions));
    setSystemPrompt(cfg.behavior?.system_prompt || "");
    setRestrictionRules(cfg.behavior?.restriction_rules || "");
    setAllowedScope(
      cfg.business?.allowed_scope ||
        cfg.behavior?.allowed_scope ||
        localStorage.getItem("allowed_scope") ||
        ""
    );
    setBlockedClaims(
      cfg.business?.blocked_claims ||
        cfg.behavior?.blocked_claims ||
        localStorage.getItem("blocked_claims") ||
        ""
    );
    setOpeningTime(cfg.support_hours?.opening_time || "09:00 AM");
    setClosingTime(cfg.support_hours?.closing_time || "06:00 PM");
    setWorkingDays(cfg.support_hours?.working_days || "Monday - Saturday");
  };

  const fetchAgentConfig = async () => {
    setIsLoading(true);
    setError("");

    try {
      const response = await fetch(
        `${API_BASE_URL}/agent-config?agent_type=${getSelectedAgentType()}`,
        {
        headers: {
          Authorization: `Bearer ${getToken()}`,
        },
      });

      const data = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(data?.detail || "Could not load agent configuration.");
      }

      hydrateForm(data);
      setSuccess("");
    } catch (err) {
      setError(err.message || "Could not load agent configuration.");
    } finally {
      setIsLoading(false);
    }
  };
  const saveAgentConfig = async (goNext = false) => {
  setIsSaving(true);
  setError("");
  setSuccess("");

  const cleanStarterQuestions = [
    ...starterQuestions,
    newQuestion.trim(),
  ].filter((q) => q.trim());

  try {
    const response = await fetch(
      `${API_BASE_URL}/agent-config?agent_type=${getSelectedAgentType()}`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${getToken()}`,
        },
        body: JSON.stringify({
          agent_type: getSelectedAgentType(),
          business_name: businessName,
          industry,
          business_type: businessType,
          business_description: businessDescription,
          website_url: websiteUrl,
          greeting_message: greetingMessage,
          starter_questions: cleanStarterQuestions,
          system_prompt: systemPrompt,
          restriction_rules: restrictionRules,
          allowed_scope: allowedScope,
          blocked_claims: blockedClaims,
          support_hours: {
            opening_time: openingTime,
            closing_time: closingTime,
            working_days: workingDays,
          },
        }),
      }
    );

    const data = await response.json().catch(() => null);

    if (!response.ok) {
      throw new Error(data?.detail || "Could not save agent configuration.");
    }

    setStarterQuestions(cleanStarterQuestions);
    setNewQuestion("");
    setSuccess(data?.message || "Agent settings saved successfully.");
  // const saveAgentConfig = async (goNext = false) => {
  //   setIsSaving(true);
  //   setError("");
  //   setSuccess("");

  //   try {
  //     const response = await fetch(
  //       `${API_BASE_URL}/agent-config?agent_type=${getSelectedAgentType()}`,
  //       {
  //       method: "POST",
  //       headers: {
  //         "Content-Type": "application/json",
  //         Authorization: `Bearer ${getToken()}`,
  //       },
  //       body: JSON.stringify({
  //         agent_type: getSelectedAgentType(),
  //         business_name: businessName,
  //         industry,
  //         business_type: businessType,
  //         business_description: businessDescription,
  //         greeting_message: greetingMessage,
  //         starter_questions: starterQuestions.filter((q) => q.trim()),
  //         system_prompt: systemPrompt,
  //         restriction_rules: restrictionRules,
  //         allowed_scope: allowedScope,
  //         blocked_claims: blockedClaims,
  //         support_hours: {
  //           opening_time: openingTime,
  //           closing_time: closingTime,
  //           working_days: workingDays,
  //         },
  //       }),
  //     });

  //     const data = await response.json().catch(() => null);

  //     if (!response.ok) {
  //       throw new Error(data?.detail || "Could not save agent configuration.");
  //     }

  //     setSuccess(data?.message || "Agent settings saved successfully.");
  //     setSuccess(data?.message || "Agent settings saved successfully.");

      if (goNext) {
        const agentType = localStorage.getItem("selected_agent_type") || "chat";
        window.location.href = agentType === "product" ? "/product-public-url" : "/step3";
      }
    } catch (err) {
      setError(err.message || "Could not save agent configuration.");
    } finally {
      setIsSaving(false);
    }
  };

  async function loadPublicLink() {
    setUrlLoading(true);
    setError("");
    setCopied(false);

    try {
      const res = await fetch(`${API_BASE_URL}${publicLinkPath()}`, {
        headers: {
          Authorization: `Bearer ${getToken()}`,
        },
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.detail || "Unable to load public link");
      }

      setLinkData(data);
      setSweetName(data.sweet_name || "");
    } catch (err) {
      setError(err.message || "Unable to load public link");
    } finally {
      setUrlLoading(false);
    }
  }

  async function saveSweetName() {
    setUrlSaving(true);
    setError("");
    setSuccess("");
    setCopied(false);

    try {
      const res = await fetch(`${API_BASE_URL}${publicLinkPath()}`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${getToken()}`,
        },
        body: JSON.stringify({
          sweet_name: sweetName,
          agent_type: getSelectedAgentType(),
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.detail || "Unable to save public URL");
      }

      setLinkData(data);
      setSweetName(data.sweet_name || "");
      setSuccess("Public URL saved successfully.");
      setShowUrlPopup(false);
    } catch (err) {
      setError(err.message || "Unable to save public URL");
    } finally {
      setUrlSaving(false);
    }
  }

  async function copyPublicUrl() {
    if (!linkData?.public_url) return;

    try {
      await navigator.clipboard.writeText(linkData.public_url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      setError("Copy failed. Please copy the URL manually.");
    }
  }

  const openUrlPopup = () => {
    setShowUrlPopup(true);
    loadPublicLink();
  };

  const updateStarterQuestion = (index, value) => {
    setStarterQuestions((prev) =>
      prev.map((item, i) => (i === index ? value : item))
    );
  };

  const removeStarterQuestion = (index) => {
    setStarterQuestions((prev) => prev.filter((_, i) => i !== index));
  };

  const addStarterQuestion = () => {
    const clean = newQuestion.trim();
    if (!clean) return;

    setStarterQuestions((prev) => [...prev, clean].slice(0, 8));
    setNewQuestion("");
  };

  if (isLoading) {
    return (
      <div className="min-h-[calc(100vh-72px)] bg-[#f6f8fc]">
        <PageHeader />
        <AgentSteps current={(localStorage.getItem("selected_agent_type") || "chat") === "product" ? 3 : 4} />

        <div className="flex min-h-[420px] items-center justify-center">
          <div className="inline-flex items-center gap-3 rounded-2xl bg-white px-6 py-4 text-sm font-bold text-slate-600 shadow-sm">
            <Loader2 className="h-5 w-5 animate-spin text-purple-600" />
            Loading agent configuration...
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-[calc(100vh-72px)] bg-[#f6f8fc]">
      <PageHeader />
      <AgentSteps current={(localStorage.getItem("selected_agent_type") || "chat") === "product" ? 3 : 4} />

      <main className="mx-auto max-w-[720px] px-5 py-7">
        {error && (
          <div className="mb-5 flex items-start gap-3 rounded-2xl border border-red-200 bg-red-50 px-5 py-4 text-sm text-red-700">
            <AlertCircle className="mt-0.5 h-5 w-5" />
            {error}
          </div>
        )}

        {success && (
          <div className="mb-5 rounded-2xl border border-emerald-200 bg-emerald-50 px-5 py-4 text-sm font-bold text-emerald-700">
            {success}
          </div>
        )}

        <div className="mb-5 rounded-2xl border border-emerald-200 bg-emerald-50 px-5 py-4">
          <div className="flex items-center justify-between gap-4">
            <div>
              <p className="text-sm font-extrabold text-emerald-700">
                Agent trained successfully!
              </p>
              <p className="text-xs font-semibold text-emerald-600">
                Scanned {knowledgeBase.website_documents || 0} pages • Uploaded{" "}
                {knowledgeBase.uploaded_documents || 0} files • Created{" "}
                {knowledgeBase.entries || 0} knowledge entries
              </p>
            </div>

            <button
              onClick={() => (window.location.href = "/train")}
              className="text-xs font-bold text-emerald-700"
            >
              Re-scan
            </button>
          </div>
        </div>

        <div className="mb-5 flex justify-end">
          <button
            onClick={openUrlPopup}
            className="inline-flex items-center gap-2 rounded-xl bg-purple-500 px-5 py-3 text-sm font-bold text-white shadow-sm hover:bg-[var(--btn-hover-color)]"
          >
            <ExternalLink className="h-4 w-4" />
            Customize URL
          </button>
        </div>

        <Card title="Business Info" icon={Bot}>
          <div className="grid gap-4 sm:grid-cols-3">
            <Field label="Name" value={businessName} onChange={setBusinessName} />
            <Field label="Industry" value={industry} onChange={setIndustry} />
            <Field label="Type" value={businessType} onChange={setBusinessType} />
          </div>
        </Card>
        <Card title="Website URL" icon={ExternalLink}>
        <Field
          label="Website URL"
          value={websiteUrl}
          onChange={setWebsiteUrl}
        />
      </Card>
        <Card title="Description" icon={BookOpen}>
          <textarea
            value={businessDescription}
            onChange={(e) => setBusinessDescription(e.target.value)}
            className="h-28 w-full resize-none rounded-xl border border-slate-200 px-4 py-3 text-sm leading-6 outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
          />
        </Card>

        <Card title="Tenant Business Rules" icon={Shield}>
          <Label>Allowed Scope</Label>
          <textarea
            value={allowedScope}
            onChange={(e) => setAllowedScope(e.target.value)}
            placeholder="Example: product information, specifications, images, catalog details, product support"
            className="h-24 w-full resize-none rounded-xl border border-slate-200 px-4 py-3 text-sm leading-6 outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
          />

          <Label className="mt-4">Blocked Claims</Label>
          <textarea
            value={blockedClaims}
            onChange={(e) => setBlockedClaims(e.target.value)}
            placeholder="Example: installation services, repair services, maintenance services, on-site services, unconfirmed pricing"
            className="h-24 w-full resize-none rounded-xl border border-slate-200 px-4 py-3 text-sm leading-6 outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
          />

          <p className="mt-3 rounded-xl bg-slate-50 p-3 text-xs leading-5 text-slate-500">
            These rules are saved tenant-wise and injected into chatbot.py before every Groq answer.
          </p>
        </Card>


        <Card title="Knowledge Base" icon={BookOpen}>
          <div className="flex flex-wrap items-center gap-2">
            <Badge>{knowledgeBase.entries || 0} entries</Badge>
            <Badge>{knowledgeBase.website_documents || 0} website pages</Badge>
            <Badge>{knowledgeBase.uploaded_documents || 0} uploaded files</Badge>
            <Badge>{knowledgeBase.total_vectors || 0} total vectors</Badge>
          </div>
        </Card>

        <div className="mb-5 rounded-2xl border border-purple-200 bg-purple-50 p-5">
          <div className="mb-4 flex items-center gap-2 text-purple-700">
            <Sparkles className="h-4 w-4" />
            <h3 className="text-sm font-extrabold">What your AI agent knows</h3>
          </div>

          <div className="text-sm leading-6 text-purple-700">
            <p>
              Your AI agent “
              {businessName || config?.tenant?.tenant_name || "your business"}”
              knows:
            </p>
            <p>📄 {knowledgeBase.entries || 0} knowledge base entries</p>
            <p>🌐 {knowledgeBase.website_documents || 0} website pages</p>
            <p>📎 {knowledgeBase.uploaded_documents || 0} uploaded documents</p>
            <p>🔍 Your chatbot can answer questions from this trained data.</p>

            {processedSources.length > 0 && (
              <p>✅ Processed sources: {processedSources.slice(0, 3).join(", ")}</p>
            )}

            {skippedSources.length > 0 && (
              <p>⏭ Skipped duplicates: {skippedSources.length}</p>
            )}

            {failedSources.length > 0 && (
              <p>⚠ Failed sources: {failedSources.length}</p>
            )}
          </div>
        </div>

        <Card title="Chat Experience" icon={MessageSquare}>
          <Label>Greeting Message</Label>
          <textarea
            value={greetingMessage}
            onChange={(e) => setGreetingMessage(e.target.value)}
            className="h-20 w-full resize-none rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
          />

          <Label className="mt-4">Starter Questions</Label>

          {starterQuestions.map((q, index) => (
            <div key={index} className="mb-2 flex gap-2">
              <input
                value={q}
                onChange={(e) => updateStarterQuestion(index, e.target.value)}
                className="h-10 flex-1 rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-purple-400"
              />

              <button
                onClick={() => removeStarterQuestion(index)}
                className="h-10 w-10 rounded-lg border border-slate-200 text-slate-400 hover:text-red-500"
              >
                ×
              </button>
            </div>
          ))}

          <div className="flex gap-2">
            <input
              value={newQuestion}
              onChange={(e) => setNewQuestion(e.target.value)}
              placeholder="Add question (max 50 chars)..."
              className="h-10 flex-1 rounded-lg border border-dashed border-slate-300 px-3 text-sm outline-none"
            />

            <button
              onClick={addStarterQuestion}
              className="h-10 w-10 rounded-lg bg-purple-100 text-purple-600"
            >
              +
            </button>
          </div>
        </Card>

        <Card title="AI Behaviour & Rules" icon={Shield}>
          <Label>System Prompt</Label>
          <textarea
            value={systemPrompt}
            onChange={(e) => setSystemPrompt(e.target.value)}
            className="h-32 w-full resize-none rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
          />

          <Label className="mt-4">Restriction Rules</Label>
          <textarea
            value={restrictionRules}
            onChange={(e) => setRestrictionRules(e.target.value)}
            className="h-28 w-full resize-none rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
          />

          <p className="mt-2 text-xs text-slate-400">
            If this is left empty, backend will automatically save safe default
            rules.
          </p>
        </Card>

        <Card title="Support Hours" icon={Clock}>
          <p className="mb-4 text-xs text-slate-400">
            Set your business hours so the chatbot can tell customers when live
            support is available.
          </p>

          <div className="grid grid-cols-2 gap-4">
            <Field label="Opening Time" value={openingTime} onChange={setOpeningTime} />
            <Field label="Closing Time" value={closingTime} onChange={setClosingTime} />
          </div>

          <div className="mt-4">
            <Field label="Working Days" value={workingDays} onChange={setWorkingDays} />
          </div>
        </Card>

        <div className="mt-8 flex items-center justify-between">
          <button
            onClick={() => (window.location.href = "/step2")}
            className="rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-bold text-slate-600 shadow-sm"
          >
            ← Back
          </button>

          <div className="flex gap-3">
            <button
              onClick={() => saveAgentConfig(false)}
              disabled={isSaving}
              className="inline-flex items-center gap-2 rounded-xl border border-purple-200 bg-white px-5 py-3 text-sm font-bold text-purple-600 shadow-sm disabled:opacity-60"
            >
              {isSaving ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Save className="h-4 w-4" />
              )}
              Save
            </button>

            <button
              onClick={() => saveAgentConfig(true)}
              disabled={isSaving}
              className="rounded-xl bg-purple-500 px-7 py-3 text-sm font-bold text-white shadow-sm hover:bg-[var(--btn-hover-color)] disabled:opacity-60"
            >
              Continue
            </button>
          </div>
        </div>
      </main>

      {showUrlPopup && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 px-4">
          <div className="w-full max-w-2xl rounded-2xl bg-white p-6 shadow-xl">
            <div className="mb-4 flex items-center justify-between">
              <h3 className="text-lg font-extrabold text-slate-800">
                {getSelectedAgentType() === "product" ? "Customize Product Bot URL" : "Customize Public Chat URL"}
              </h3>

              <button
                onClick={() => setShowUrlPopup(false)}
                className="rounded-lg p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-700"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            {urlLoading ? (
              <div className="flex items-center gap-3 rounded-xl bg-slate-50 px-4 py-5 text-sm font-bold text-slate-600">
                <Loader2 className="h-5 w-5 animate-spin text-purple-600" />
                Loading public URL...
              </div>
            ) : (
              <>
                <Label>{getSelectedAgentType() === "product" ? "Original Product Bot URL" : "Original Chat URL"}</Label>
                <input
                  value={linkData?.original_url || ""}
                  readOnly
                  className="mb-4 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none"
                />

                <Label>Sweet Name</Label>
                <div className="mb-2 flex gap-2">
                  <span className="rounded-xl bg-slate-100 px-4 py-3 text-sm text-slate-600">
                    {window.location.origin}/
                  </span>

                  <input
                    value={sweetName}
                    onChange={(e) => setSweetName(e.target.value)}
                    placeholder={linkData?.short_code || "A8X9K2PQ"}
                    className="flex-1 rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
                  />
                </div>

                <p className="mb-4 text-xs text-slate-400">
                  Use 3-50 characters. Letters, numbers, hyphen, and underscore
                  are allowed. If empty, your 8-character code is used.
                </p>

                <Label>Public Share URL</Label>
                <input
                  value={linkData?.public_url || ""}
                  readOnly
                  className="mb-5 w-full rounded-xl border border-slate-200 px-4 py-3 text-sm outline-none"
                />

                <div className="flex flex-wrap justify-end gap-3">
                  <button
                    onClick={copyPublicUrl}
                    className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-bold text-slate-600"
                  >
                    <Copy className="h-4 w-4" />
                    {copied ? "Copied" : "Copy Link"}
                  </button>

                  <button
                    onClick={() => setShowUrlPopup(false)}
                    className="rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-bold text-slate-600"
                  >
                    Cancel
                  </button>

                  <button
                    onClick={saveSweetName}
                    disabled={urlSaving}
                    className="inline-flex items-center gap-2 rounded-xl bg-purple-500 px-5 py-3 text-sm font-bold text-white disabled:opacity-60"
                  >
                    {urlSaving && <Loader2 className="h-4 w-4 animate-spin" />}
                    {urlSaving ? "Saving..." : "Save URL"}
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

