import React, { useMemo, useState } from "react";
import { Loader2, Lock, Mail, Sparkles, Eye, EyeOff } from "lucide-react";

const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL || "http://localhost:8000";

function getEmailFromQuery() {
  try {
    return new URLSearchParams(window.location.search).get("email") || "";
  } catch {
    return "";
  }
}

export default function SetPass() {
  const initialEmail = useMemo(() => getEmailFromQuery(), []);

  const [email, setEmail] = useState(initialEmail);
  const [otp, setOtp] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  const canSubmit =
    email.trim() && otp.trim() && password.trim() && confirmPassword.trim() && !isLoading;

  const resetPassword = async () => {
    setError("");
    setSuccess("");

    if (!email.trim() || !otp.trim() || !password.trim() || !confirmPassword.trim()) {
      setError("Please fill email, OTP, password and confirm password.");
      return;
    }

    if (password !== confirmPassword) {
      setError("Password and confirm password do not match.");
      return;
    }

    if (password.length < 6) {
      setError("Password must be at least 6 characters.");
      return;
    }

    try {
      setIsLoading(true);

      const response = await fetch(`${API_BASE_URL}/auth/reset-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: email.trim(),
          otp: otp.trim(),
          new_password: password,
        }),
      });

      const result = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(result?.detail || "Password reset failed.");
      }

      setSuccess(result?.message || "Password reset successfully.");

      setTimeout(() => {
        window.location.href = "/";
      }, 1200);
    } catch (err) {
      setError(err.message || "Something went wrong.");
    } finally {
      setIsLoading(false);
    }
  };

  const onKeyDown = (e) => {
    if (e.key === "Enter") {
      resetPassword();
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center px-4">
      <div className="w-full max-w-md rounded-3xl bg-white p-8 shadow-sm ring-1 ring-slate-200">
        <div className="text-center">
          <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-3xl bg-purple-100">
            <Sparkles className="h-8 w-8 text-purple-600" />
          </div>

          <h1 className="text-2xl font-extrabold text-slate-900">
            Set New Password
          </h1>
          <p className="mt-2 text-sm text-slate-500">
            Enter the OTP sent to your email and create a new password.
          </p>
        </div>

        <div className="mt-8 space-y-4">
          <label className="block">
            <span className="mb-2 block text-sm font-semibold text-slate-700">
              Email
            </span>
            <div className="flex items-center rounded-xl border border-slate-200 bg-white px-4 py-3 focus-within:border-[var(--primary-color)] focus-within:ring-2 focus-within:ring-purple-100">
              <Mail className="mr-3 h-5 w-5 text-slate-400" />
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onKeyDown={onKeyDown}
                placeholder="you@company.com"
                className="w-full bg-transparent outline-none"
              />
            </div>
          </label>

          <label className="block">
            <span className="mb-2 block text-sm font-semibold text-slate-700">
              OTP
            </span>
            <div className="flex items-center rounded-xl border border-slate-200 bg-white px-4 py-3 focus-within:border-[var(--primary-color)] focus-within:ring-2 focus-within:ring-purple-100">
              <input
                type="text"
                inputMode="numeric"
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
                onKeyDown={onKeyDown}
                placeholder="Enter OTP"
                className="w-full bg-transparent outline-none"
              />
            </div>
          </label>

          <label className="block">
            <span className="mb-2 block text-sm font-semibold text-slate-700">
              New Password
            </span>
            <div className="flex items-center rounded-xl border border-slate-200 bg-white px-4 py-3 focus-within:border-[var(--primary-color)] focus-within:ring-2 focus-within:ring-purple-100">
              <Lock className="mr-3 h-5 w-5 text-slate-400" />
              <input
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                onKeyDown={onKeyDown}
                placeholder="Enter New Password"
                className="w-full bg-transparent outline-none"
              />
              <button
                type="button"
                onClick={() => setShowPassword((prev) => !prev)}
                className="ml-2 text-purple-600"
              >
                {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
              </button>
            </div>
          </label>

          <label className="block">
            <span className="mb-2 block text-sm font-semibold text-slate-700">
              Confirm Password
            </span>
            <div className="flex items-center rounded-xl border border-slate-200 bg-white px-4 py-3 focus-within:border-[var(--primary-color)] focus-within:ring-2 focus-within:ring-purple-100">
              <Lock className="mr-3 h-5 w-5 text-slate-400" />
              <input
                type={showConfirmPassword ? "text" : "password"}
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                onKeyDown={onKeyDown}
                placeholder="Confirm Password"
                className="w-full bg-transparent outline-none"
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword((prev) => !prev)}
                className="ml-2 text-purple-600"
              >
                {showConfirmPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
              </button>
            </div>
          </label>

          {error && (
            <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
              {error}
            </div>
          )}

          {success && (
            <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">
              {success}
            </div>
          )}

          <button
            type="button"
            onClick={resetPassword}
            disabled={!canSubmit}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-purple-600 px-5 py-3 font-bold text-white shadow-sm hover:bg-[var(--btn-hover-color)] disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isLoading ? (
              <>
                <Loader2 className="h-5 w-5 animate-spin" />
                Updating Password...
              </>
            ) : (
              "Submit"
            )}
          </button>

          <div className="text-right">
            <button
              type="button"
              onClick={() => (window.location.href = "/")}
              className="text-sm font-medium text-purple-600 underline"
            >
              Back to Sign in
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
