import React, { useEffect, useMemo, useState } from "react";
import AddKnowledgeEntryModal from "./AddKnowledgeEntryModal";
// import "./Style.css";

const API_BASE = process.env.REACT_APP_API_BASE_URL || "";

function getToken() {
  return localStorage.getItem("auth_token") || "";
}

function safeList(value) {
  return Array.isArray(value) ? value : [];
}

function listToText(value) {
  return safeList(value).join("\n");
}

function textToList(value) {
  return String(value || "")
    .split(/\n|,/)
    .map((x) => x.trim())
    .filter(Boolean);
}

async function apiFetch(path, options = {}) {
  const token = getToken();
  const response = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers: {
      ...(options.headers || {}),
      Authorization: `Bearer ${token}`,
    },
  });

  if (!response.ok) {
    let message = "Request failed";
    try {
      const data = await response.json();
      message = data.detail || message;
    } catch (_) {}
    throw new Error(message);
  }

  return response.json();
}

export default function KnowledgeBase() {
  const [entries, setEntries] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(false);
  const [savingId, setSavingId] = useState("");
  const [error, setError] = useState("");
  const [editingId, setEditingId] = useState("");
  const [form, setForm] = useState({});
  const [showAddModal, setShowAddModal] = useState(false);

  const filteredCount = useMemo(() => entries.length, [entries]);

  async function loadEntries(value = search) {
    setLoading(true);
    setError("");
    try {
      const query = value ? `?search=${encodeURIComponent(value)}` : "";
      const data = await apiFetch(`/knowledge${query}`);
      setEntries(data.entries || []);
    } catch (err) {
      setError(err.message || "Unable to load knowledge base.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadEntries("");
   
  }, []);

  async function startEdit(entry) {
    setEditingId(entry.id);
    setSavingId(entry.id);
    setError("");

    try {
      // Load the single KB entry before editing because list API only shows preview.
      // GET /knowledge/{id} returns the full text from the saved .txt file.
      const data = await apiFetch(`/knowledge/${entry.id}`);
      const fullEntry = data.entry || entry;

      setForm({
        title: fullEntry.title || "",
        page_type: fullEntry.page_type || "website_page",
        priority: fullEntry.priority || 0,
        url: fullEntry.url || "",
        tags: listToText(fullEntry.tags || []),
        images: listToText(fullEntry.images || []),
        links: listToText(fullEntry.links || []),
        text: fullEntry.text || fullEntry.preview || "",
        is_disabled: Boolean(fullEntry.is_disabled || fullEntry.status === "disabled"),
      });
    } catch (err) {
      setError(err.message || "Unable to load full knowledge text.");
      setForm({
        title: entry.title || "",
        page_type: entry.page_type || "website_page",
        priority: entry.priority || 0,
        url: entry.url || "",
        tags: listToText(entry.tags || []),
        images: listToText(entry.images || []),
        links: listToText(entry.links || []),
        text: entry.text || entry.preview || "",
        is_disabled: Boolean(entry.is_disabled || entry.status === "disabled"),
      });
    } finally {
      setSavingId("");
    }
  }

  function cancelEdit() {
    setEditingId("");
    setForm({});
  }

  async function saveEdit(entryId) {
    setSavingId(entryId);
    setError("");
    try {
      const payload = {
        title: form.title,
        page_type: form.page_type,
        priority: Number(form.priority || 0),
        url: form.url,
        tags: textToList(form.tags),
        images: textToList(form.images),
        links: textToList(form.links),
        text: form.text,
        is_disabled: Boolean(form.is_disabled),
      };
      const data = await apiFetch(`/knowledge/${entryId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      setEntries((prev) => prev.map((entry) => (entry.id === entryId ? data.entry : entry)));
      cancelEdit();
      await loadEntries(search);
    } catch (err) {
      setError(err.message || "Unable to save knowledge entry.");
    } finally {
      setSavingId("");
    }
  }

  async function toggleEntry(entry) {
    setSavingId(entry.id);
    setError("");
    try {
      const path = entry.is_disabled || entry.status === "disabled"
        ? `/knowledge/${entry.id}/enable`
        : `/knowledge/${entry.id}/disable`;
      const data = await apiFetch(path, { method: "POST" });
      setEntries((prev) => prev.map((item) => (item.id === entry.id ? data.entry : item)));
    } catch (err) {
      setError(err.message || "Unable to update entry status.");
    } finally {
      setSavingId("");
    }
  }

  async function rebuildIndex() {
    setLoading(true);
    setError("");
    try {
      await apiFetch("/knowledge/rebuild-index", { method: "POST" });
      await loadEntries(search);
    } catch (err) {
      setError(err.message || "Unable to rebuild knowledge index.");
    } finally {
      setLoading(false);
    }
  }


  async function handleManualEntrySubmit(payload) {
  setLoading(true);
  setError("");

  try {
    await apiFetch("/knowledge", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(payload),
    });

    setShowAddModal(false);

    await loadEntries(search);

  } catch (err) {
    setError(err.message || "Unable to add knowledge entry.");
  } finally {
    setLoading(false);
  }
}
  function downloadAll() {
    const token = getToken();
    window.open(`${API_BASE}/knowledge/download?token=${encodeURIComponent(token)}`, "_blank");
  }

  function downloadEntry(id) {
    const token = getToken();
    window.open(`${API_BASE}/knowledge/${id}/download?token=${encodeURIComponent(token)}`, "_blank");
  }

  return (
    <div className="min-h-screen bg-slate-50 p-6">
      <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Knowledge Base</h1>
          <p className="text-sm text-slate-500">
            Edit labels, tags, links, images, and answer text. Saving rebuilds this tenant&apos;s FAISS index.
          </p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setShowAddModal(true)} className="rounded-xl bg-purple-600 px-4 py-2 text-sm font-semibold text-white shadow-sm hover:opacity-90">
            + Add Entry
          </button>
          <button onClick={rebuildIndex} className="rounded-xl border border-purple-300 px-4 py-2 text-sm font-semibold text-purple-700 hover:bg-purple-50">
            Rebuild Index
          </button>
          <button onClick={downloadAll} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">
            Download All Text
          </button>
        </div>
      </div>

      <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
        <div className="mb-4 flex gap-3">
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") loadEntries(e.currentTarget.value);
            }}
            placeholder="Search title, content, product tags, links, image labels..."
            className="flex-1 rounded-xl border border-slate-200 px-4 py-2 text-sm outline-none focus:border-purple-400 focus:ring-2 focus:ring-purple-100"
          />
          <button onClick={() => loadEntries(search)} className="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-50">
            Search
          </button>
        </div>

        <div className="mb-3 text-xs text-slate-500">
          {loading ? "Loading..." : `Showing ${filteredCount} entries`}
        </div>

        {error && <div className="mb-3 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</div>}

        <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
          {entries.map((entry) => {
            const isEditing = editingId === entry.id;
            const disabled = entry.is_disabled || entry.status === "disabled";
            return (
              <div key={entry.id} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
                {!isEditing ? (
                  <>
                    <div className="mb-2 flex items-start justify-between gap-3">
                      <div>
                        <div className="font-semibold text-slate-900">{entry.title}</div>
                        <div className="mt-1 text-xs text-slate-500">
                          {entry.source_type} • {entry.content_type} • {entry.page_type || "website_page"} • {entry.text_length || 0} chars
                        </div>
                      </div>
                      <span className={`rounded-full px-2 py-1 text-xs font-semibold ${disabled ? "bg-amber-50 text-amber-700" : "bg-emerald-50 text-emerald-700"}`}>
                        {disabled ? "disabled" : "active"}
                      </span>
                    </div>

                    <p className="mb-3 line-clamp-3 text-sm text-slate-600">{entry.preview}</p>

                    <div className="mb-3 grid grid-cols-2 gap-2 text-xs">
                      <div className="rounded-xl border border-slate-100 bg-slate-50 px-3 py-2">
                        <span className="font-bold text-slate-700">Images:</span> {entry.images_count ?? safeList(entry.images).length}
                      </div>
                      <div className="rounded-xl border border-slate-100 bg-slate-50 px-3 py-2">
                        <span className="font-bold text-slate-700">Links:</span> {entry.links_count ?? safeList(entry.links).length}
                      </div>
                    </div>

                    {safeList(entry.images).length > 0 && (
                      <div className="mb-3 flex gap-2 overflow-x-auto">
                        {safeList(entry.images).slice(0, 4).map((url, index) => (
                          <a key={`${url}-${index}`} href={url} target="_blank" rel="noreferrer">
                            <img src={url} alt={`Knowledge asset ${index + 1}`} className="h-16 w-16 rounded-xl object-cover" loading="lazy" />
                          </a>
                        ))}
                      </div>
                    )}

                    <div className="mb-3 flex flex-wrap gap-2">
                      {safeList(entry.tags).map((tag) => (
                        <span key={tag} className="rounded-full bg-slate-100 px-2 py-1 text-xs text-slate-600">{tag}</span>
                      ))}
                    </div>

                    <div className="flex flex-wrap gap-2">
                      <button onClick={() => startEdit(entry)} className="rounded-xl bg-purple-600 px-3 py-2 text-xs font-semibold text-white hover:opacity-90">
                        Edit Knowledge
                      </button>
                      <button onClick={() => toggleEntry(entry)} disabled={savingId === entry.id} className="rounded-xl border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-50">
                        {disabled ? "Enable" : "Disable"}
                      </button>
                      <button onClick={() => downloadEntry(entry.id)} className="rounded-xl border border-purple-300 px-3 py-2 text-xs font-semibold text-purple-700 hover:bg-purple-100">
                        Download Text
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="space-y-3">
                    <input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="w-full rounded-xl border border-slate-200 px-3 py-2 text-sm" placeholder="Title" />
                    <div className="grid grid-cols-2 gap-2">
                      <input value={form.page_type} onChange={(e) => setForm({ ...form, page_type: e.target.value })} className="rounded-xl border border-slate-200 px-3 py-2 text-sm" placeholder="product_page / service_page / company_page" />
                      <input type="number" value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value })} className="rounded-xl border border-slate-200 px-3 py-2 text-sm" placeholder="Priority" />
                    </div>
                    <input value={form.url} onChange={(e) => setForm({ ...form, url: e.target.value })} className="w-full rounded-xl border border-slate-200 px-3 py-2 text-sm" placeholder="Main source/product URL" />
                    <textarea value={form.tags} onChange={(e) => setForm({ ...form, tags: e.target.value })} className="h-20 w-full rounded-xl border border-slate-200 px-3 py-2 text-sm" placeholder="Tags/labels, one per line or comma separated" />
                    <textarea value={form.images} onChange={(e) => setForm({ ...form, images: e.target.value })} className="h-20 w-full rounded-xl border border-slate-200 px-3 py-2 text-sm" placeholder="Image URLs, one per line" />
                    <textarea value={form.links} onChange={(e) => setForm({ ...form, links: e.target.value })} className="h-20 w-full rounded-xl border border-slate-200 px-3 py-2 text-sm" placeholder="Important links, one per line" />
                    <textarea value={form.text} onChange={(e) => setForm({ ...form, text: e.target.value })} className="h-44 w-full rounded-xl border border-slate-200 px-3 py-2 text-sm" placeholder="Exact answer/product/support knowledge text" />
                    <label className="flex items-center gap-2 text-sm text-slate-700">
                      <input type="checkbox" checked={form.is_disabled} onChange={(e) => setForm({ ...form, is_disabled: e.target.checked })} />
                      Disable this entry
                    </label>
                    <div className="flex gap-2">
                      <button onClick={() => saveEdit(entry.id)} disabled={savingId === entry.id} className="rounded-xl bg-purple-600 px-3 py-2 text-xs font-semibold text-white hover:opacity-90">
                        {savingId === entry.id ? "Saving..." : "Save & Rebuild"}
                      </button>
                      <button onClick={cancelEdit} className="rounded-xl border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-50">
                        Cancel
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {!loading && entries.length === 0 && (
          <div className="rounded-2xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500">
            No readable training entries found yet. Train your agent once and this page will show editable extracted knowledge.
          </div>
        )}
      </div>

      <AddKnowledgeEntryModal
        open={showAddModal}
        onClose={() => setShowAddModal(false)}
        onSubmit={handleManualEntrySubmit}
      />
    </div>
  );
}
