import React, { useEffect, useMemo, useState } from "react";
import { Copy, ExternalLink, Link as LinkIcon, Loader2, Plus } from "lucide-react";
import AgentSteps from "./training/AgentSteps";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || window.location.origin;

function getTenantSlug() {
  return localStorage.getItem("tenant_slug") || "t1";
}

function getToken() {
  return localStorage.getItem("auth_token") || localStorage.getItem("token") || "";
}

export default function ProductPublicUrl() {
  const tenantSlug = useMemo(() => getTenantSlug(), []);
  const defaultUrl = `${window.location.origin}/chat_${tenantSlug}`;

  const [publicUrl, setPublicUrl] = useState(defaultUrl);
  const [activeAgentType, setActiveAgentType] = useState(
    localStorage.getItem("selected_agent_type") || "chat"
  );
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function loadPublicUrl() {
      const token = getToken();

      if (!token) {
        setPublicUrl(defaultUrl);
        setLoading(false);
        return;
      }

      try {
        const res = await fetch(`${API_BASE_URL}/public-link`, {
          headers: { Authorization: `Bearer ${token}` },
        });

        const data = await res.json().catch(() => null);

        if (!res.ok) {
          throw new Error(data?.detail || "Unable to load public URL");
        }

        setPublicUrl(data?.public_url || data?.original_url || defaultUrl);
        setActiveAgentType(data?.active_agent_type || data?.agent_type || activeAgentType || "chat");
      } catch (err) {
        setError(err.message || "Unable to load public URL. Showing default URL.");
        setPublicUrl(defaultUrl);
      } finally {
        setLoading(false);
      }
    }

    loadPublicUrl();
  }, [defaultUrl]);

  const copyUrl = async () => {
    try {
      await navigator.clipboard.writeText(publicUrl);
      alert("Public URL copied.");
    } catch {
      alert(publicUrl);
    }
  };

  const agentLabel = activeAgentType === "product" ? "Product Agent" : "Chat Agent";

  return (
    <div className="min-h-[calc(100vh-72px)] bg-[#f6f8fc]">
      <div className="border-b border-slate-100 bg-white px-6 py-5 lg:px-8">
        <div className="flex items-center justify-between">
          <button className="inline-flex items-center gap-3 text-[16px] font-bold text-slate-900">
            <Plus className="h-5 w-5 text-purple-600" /> Create New Agent
          </button>
          <p className="text-xs font-semibold text-slate-400">Step 4 of 5</p>
        </div>
      </div>

      <AgentSteps current={4} />

      <main className="mx-auto max-w-4xl px-5 py-10">
        <div className="rounded-3xl border border-slate-200 bg-white p-7 shadow-sm">
          <div className="flex items-start gap-4">
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-purple-100 text-purple-600">
              <LinkIcon className="h-6 w-6" />
            </div>
            <div>
              <h2 className="text-xl font-extrabold text-slate-950">Your Public URL</h2>
              <p className="mt-1 text-sm leading-6 text-slate-500">
                Share this same URL with customers. It will open as {agentLabel} based on your tenant active agent type.
              </p>
            </div>
          </div>

          {error && (
            <div className="mt-5 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-semibold text-amber-700">
              {error}
            </div>
          )}

          <div className="mt-7 rounded-2xl border border-purple-100 bg-purple-50/40 p-5">
            <label className="mb-2 block text-xs font-bold uppercase tracking-wide text-slate-500">
              Public URL
            </label>
            <div className="flex flex-col gap-3 sm:flex-row">
              <input
                readOnly
                value={loading ? "Loading public URL..." : publicUrl}
                className="h-12 flex-1 rounded-xl border border-slate-200 bg-white px-4 text-sm text-slate-700"
              />
              <button
                onClick={copyUrl}
                disabled={loading}
                className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-5 text-sm font-bold text-purple-600 disabled:opacity-60"
              >
                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Copy className="h-4 w-4" />} Copy
              </button>
              <button
                onClick={() => window.open(publicUrl, "_blank")}
                disabled={loading}
                className="inline-flex items-center justify-center gap-2 rounded-xl bg-purple-500 px-5 text-sm font-bold text-white disabled:opacity-60"
              >
                <ExternalLink className="h-4 w-4" /> Open
              </button>
            </div>
          </div>

          <div className="mt-5 rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-600">
            Current active flow: <span className="text-purple-600">{agentLabel}</span>
          </div>

          <div className="mt-8 flex items-center justify-between">
            <button
              onClick={() => (window.location.href = "/review-agent")}
              className="rounded-xl border border-slate-200 bg-white px-5 py-3 text-sm font-bold text-slate-600 shadow-sm"
            >
              ← Back
            </button>
            <button
              onClick={() => (window.location.href = "/step3")}
              className="rounded-xl bg-purple-500 px-6 py-3 text-sm font-bold text-white shadow-sm hover:bg-[var(--btn-hover-color)]"
            >
              Continue to WhatsApp →
            </button>
          </div>
        </div>
      </main>
    </div>
  );
}



