import React from "react";
import AgentTypePage from "./components/AgentTypePage";
import TrainDoc from "./components/train_doc";
import Step2 from "./components/Step2";
import Step3 from "./components/Step3";
import ReviewAgentPage from "./components/ReviewAgentPage";
import ChatBot from "./components/ChatBot";
import SignIn from "./components/SignIn";
import ContactsDashboard from "./components/ContactsDashboard";
import KnowledgeBase from "./components/KnowledgeBase";
import DashboardLayout from "./components/layout/DashboardLayout";
import ForgotPass from "./components/ForgotPass";
import SetPass from "./components/SetPass";
import Integration from "./components/Integration";
import ProductQueryBot from "./components/ProductQueryBot";
import ProductPublicUrl from "./components/ProductPublicUrl";
import ProductAgentsPage from "./components/ProductAgentsPage";
import CustomizeBotPage from "./components/bot-customization/CustomizeBotPage";


function isLoggedIn() {
  return Boolean(localStorage.getItem("auth_token"));
}

export default function App() {
  const path = window.location.pathname;

  const publicRoutes = ["/forgot-password", "/set-password"];

  const privateRoutes = [
  "/",
  "/dashboard",
  "/agent-type",
  "/train",
  "/step2",
  "/step3",
  "/review-agent",
  "/customize-bot",
  "/contacts",
  "/knowledge-base",
  "/integration",
  "/product-chat",
  "/product-agents",
  "/product-public-url",
  "/voice-agent",
];

  // const privateRoutes = [
  //   "/",
  //   "/dashboard",
  //   "/agent-type",
  //   "/train",
  //   "/step2",
  //   "/step3",
  //   "/review-agent",
  //   "/contacts",
  //   "/knowledge-base",
  //   "/integration",
  //   "/product-chat",
  //   "/product-public-url",
  //   "/voice-agent",
  // ];

  const isChatRoute = path.startsWith("/chat/") || path.startsWith("/chat_");
  const isPublicProductRoute =
    path.startsWith("/product-chat_") || path.startsWith("/product-chat/");

  const isCustomPublicChatRoute =
    !publicRoutes.includes(path) &&
    !privateRoutes.includes(path) &&
    !isChatRoute &&
    !isPublicProductRoute;

  if (path === "/forgot-password") return <ForgotPass />;
  if (path === "/set-password") return <SetPass />;

  if (isChatRoute || isPublicProductRoute || isCustomPublicChatRoute) {
    return <ChatBot />;
  }

  if (!isLoggedIn()) return <SignIn />;

  if (path === "/contacts") return <ContactsDashboard />;

  if (path === "/knowledge-base") {
    return (
      <DashboardLayout title="Knowledge Base">
        <KnowledgeBase />
      </DashboardLayout>
    );
  }

  if (path === "/integration") {
    return (
      <DashboardLayout title="Integration">
        <Integration />
      </DashboardLayout>
    );
  }

  if (path === "/product-agents") {
    return (
      <DashboardLayout title="Product Bots">
        <ProductAgentsPage />
      </DashboardLayout>
    );
  }

  if (path === "/product-chat" || path === "/voice-agent") {
    return (
      <DashboardLayout title="Product Agent">
        <ProductQueryBot />
      </DashboardLayout>
    );
  }

  if (path === "/product-public-url") {
    return (
      <DashboardLayout title="Public URL">
        <ProductPublicUrl />
      </DashboardLayout>
    );
  }

  if (path === "/" || path === "/dashboard" || path === "/agent-type") {
    return (
      <DashboardLayout title="Chat Agents">
        <AgentTypePage />
      </DashboardLayout>
    );
  }

  if (path === "/train") {
    return (
      <DashboardLayout title="Train Agent">
        <TrainDoc />
      </DashboardLayout>
    );
  }

  if (path === "/step2") {
    return (
      <DashboardLayout title="Training">
        <Step2 />
      </DashboardLayout>
    );
  }

  if (path === "/review-agent") {
    return (
      <DashboardLayout title="Customize Agent">
        <ReviewAgentPage />
      </DashboardLayout>
    );
  }
  if (path === "/customize-bot") {
  return (
    <DashboardLayout title="Customize Bot">
      <CustomizeBotPage />
    </DashboardLayout>
  );
}
  if (path === "/step3") {
    return (
      <DashboardLayout title="Connect WhatsApp">
        <Step3 />
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout title="Chat Agents">
      <AgentTypePage />
    </DashboardLayout>
  );
}