import React, { useState } from "react";
import AgentSteps from "./training/AgentSteps";


const API_BASE = process.env.REACT_APP_API_BASE_URL || "";

function getSelectedAgentId() {
  const params = new URLSearchParams(window.location.search || "");
  return params.get("agent_id") || localStorage.getItem("selected_product_agent_id") || "";
}

export default function Integration() {
  const [form, setForm] = useState({
    company_name: "",
    platform: "",
    db_host: "",
    db_port: "3306",
    db_user: "",
    db_password: "",
    db_name: "",
    website_url: "",
  });

  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState("");

  const platforms = [
    { label: "WordPress", value: "wordpress" },
    { label: "Shopify", value: "shopify" },
    { label: "Wix", value: "wix" },
    { label: "React", value: "react" },
    { label: "HTML Website", value: "html" },
    { label: "Next.js", value: "nextjs" },
  ];

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  const saveIntegration = async (e) => {
    e.preventDefault();
    setMsg("");
    setLoading(true);

    try {
      const payload = {
        ...form,
        db_port: Number(form.db_port || 3306),
        tenant_id: localStorage.getItem("tenant_id")
          ? Number(localStorage.getItem("tenant_id"))
          : null,
        tenant_slug: localStorage.getItem("tenant_slug") || null,
        agent_id: getSelectedAgentId() ? Number(getSelectedAgentId()) : null,
      };

      const res = await fetch(`${API_BASE}/integration/save`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.getItem("auth_token") || ""}`,
        },
        body: JSON.stringify(payload),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.detail || "Failed to save integration");
      }

      localStorage.setItem("selected_agent_type", "product");
      setMsg("Integration details saved successfully. Redirecting...");

      setTimeout(() => {
        const agentId = getSelectedAgentId();
        window.location.href = agentId ? `/review-agent?agent_type=product&agent_id=${agentId}` : "/review-agent";
      }, 700);
    } catch (err) {
      setMsg(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-gray-50 min-h-screen">
      <AgentSteps current={2} />
      <div className="p-6">
      <div className="max-w-5xl mx-auto">
        <div className="bg-white rounded-2xl shadow-sm border p-6">
          <h1 className="text-2xl font-bold text-gray-800 mb-2">
            Integration
          </h1>

          <p className="text-gray-500 mb-6">
            Connect your website platform and live database details for chatbot.
          </p>

          {msg && (
            <div className="mb-5 p-3 rounded-lg bg-purple-50 text-purple-700 border border-purple-200">
              {msg}
            </div>
          )}

          <form onSubmit={saveIntegration} className="space-y-6">
            <div>
              <label className="block font-semibold mb-2">
                Company Name
              </label>
              <input
                type="text"
                name="company_name"
                value={form.company_name}
                onChange={handleChange}
                className="w-full border rounded-lg px-4 py-3"
                placeholder="Enter company name"
              />
            </div>

            <div>
              <label className="block font-semibold mb-3">
                Select Website Platform
              </label>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {platforms.map((item) => (
                  <button
                    type="button"
                    key={item.value}
                    onClick={() =>
                      setForm({ ...form, platform: item.value })
                    }
                    className={`border rounded-xl p-4 text-center font-medium transition ${
                      form.platform === item.value
                        ? "bg-purple-600 text-white border-purple-600"
                        : "bg-white hover:bg-purple-50"
                    }`}
                  >
                    {item.label}
                  </button>
                ))}
              </div>
            </div>

            <div className="border-t pt-6">
              <h2 className="text-lg font-bold mb-4">
                Database Details
              </h2>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div>
                  <label className="block font-semibold mb-2">
                    DB Host
                  </label>
                  <input
                    type="text"
                    name="db_host"
                    value={form.db_host}
                    onChange={handleChange}
                    required
                    className="w-full border rounded-lg px-4 py-3"
                    placeholder="localhost or server IP"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-2">
                    DB Port
                  </label>
                  <input
                    type="number"
                    name="db_port"
                    value={form.db_port}
                    onChange={handleChange}
                    required
                    className="w-full border rounded-lg px-4 py-3"
                    placeholder="3306"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-2">
                    DB User
                  </label>
                  <input
                    type="text"
                    name="db_user"
                    value={form.db_user}
                    onChange={handleChange}
                    required
                    className="w-full border rounded-lg px-4 py-3"
                    placeholder="Database username"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-2">
                    DB Password
                  </label>
                  <input
                    type="password"
                    name="db_password"
                    value={form.db_password}
                    onChange={handleChange}
                    required
                    className="w-full border rounded-lg px-4 py-3"
                    placeholder="Database password"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-2">
                    DB Name
                  </label>
                  <input
                    type="text"
                    name="db_name"
                    value={form.db_name}
                    onChange={handleChange}
                    required
                    className="w-full border rounded-lg px-4 py-3"
                    placeholder="Database name"
                  />
                </div>

                <div>
                  <label className="block font-semibold mb-2">
                    Website URL
                  </label>
                  <input
                    type="text"
                    name="website_url"
                    value={form.website_url}
                    onChange={handleChange}
                    className="w-full border rounded-lg px-4 py-3"
                    placeholder="https://example.com"
                  />
                </div>
              </div>
            </div>

            <button
              type="submit"
              disabled={loading || !form.platform}
              className="bg-purple-600 text-white px-6 py-3 rounded-lg font-semibold hover:bg-purple-700 disabled:opacity-60"
            >
              {loading ? "Saving..." : "Save Integration"}
            </button>
          </form>
        </div>
      </div>
      </div>
    </div>
  );
}